"""Preflight the derived index sides a review reads; no canonical dataset layout is created."""

from pathlib import Path
from typing import Literal

import apsw

from agents_remember.memory.knowledge.logical import dataset_identity
from agents_remember.memory.knowledge.refusals import KnowledgeStorageError
from agents_remember.models.knowledge.candidate import SnapshotIdentity
from agents_remember.models.knowledge.review import ReviewRefusal

NOT_RECORDED: Literal["not-recorded"] = "not-recorded"


def read_dataset_identity(database: Path) -> SnapshotIdentity | str:
    """The selected index's identity, or the reason it cannot be read."""
    if not database.is_file():
        return f"the index {database} is not a file"
    try:
        return dataset_identity(database)
    except (KnowledgeStorageError, apsw.Error, OSError) as error:
        return f"the index {database} could not be read ({error})"


def unreadable_half_refusal(
    baseline_database: Path, candidate_database: Path
) -> ReviewRefusal | None:
    for half, database in (("baseline", baseline_database), ("candidate", candidate_database)):
        if not database.is_file():
            continue
        reading = read_dataset_identity(database)
        if isinstance(reading, str):
            return ReviewRefusal(
                code="candidate_dataset_absent",
                detail=f"the {half} index cannot be read: {reading}",
                next_action="rebuild the index from the recorded memory tree, then reopen the review",
                offending_input=half,
            )
    return None

"""Reopen a leaf from its exact tree record, or preserve its historical source identities.

Legacy generation JSON still records source and evidence identities. Its canonical dataset sides
are unavailable; no database snapshot or current memory tree substitutes for those sides.
"""

from __future__ import annotations

from dataclasses import dataclass, replace

from agents_remember.application.review_candidate_resolution import (
    ReviewCandidateResolution,
    recorded_leaf_contract,
    refusal,
)
from agents_remember.application.review_comparison_generation import (
    ComparisonGenerationManifest,
)
from agents_remember.application.review_comparison_reopen import (
    ComparisonReopen,
    reopen_comparison_generation,
)
from agents_remember.application.review_legacy_comparison import (
    LEGACY_UNAVAILABLE,
    legacy_comparison_resolution,
)
from agents_remember.application.review_tree_comparison import reopen_review_trees, tree_resolution
from agents_remember.kernel.primitives.runtime_config import McpRuntimeConfig
from agents_remember.models.knowledge.review import ReviewRefusal


@dataclass(frozen=True)
class ClosedLeafReview:
    """An existing historical JSON record and its source/evidence availability."""

    reopened: ComparisonReopen
    sentence: str

    @property
    def manifest(self) -> ComparisonGenerationManifest | None:
        return self.reopened.manifest

    @property
    def state(self) -> str:
        return "recorded-comparison" if self.manifest is not None else "recorded-source-range"

    @property
    def generation_id(self) -> str | None:
        generation = self.reopened.generation
        return None if generation is None else generation.generation_id


def resolve_committed_leaf_review(
    config: McpRuntimeConfig,
    repository_id: str,
    master: str,
    leaf_id: str,
    *,
    generation_id: str | None = None,
) -> ReviewCandidateResolution | ReviewRefusal:
    contract = recorded_leaf_contract(config, repository_id, master, leaf_id)
    if contract is None:
        return refusal(
            "candidate_unresolved",
            "no readable enclosure records this leaf",
            next_action="name the leaf's existing enclosure",
            offending_input=leaf_id,
        )
    if generation_id is None:
        trees = reopen_review_trees(config.coordination_root, contract)
        if isinstance(trees, ReviewRefusal):
            return trees
        if trees is not None:
            return tree_resolution(repository_id, contract, trees)
    reopened = reopen_comparison_generation(
        config, repository_id, master, leaf_id, generation_id=generation_id
    )
    if reopened.refusal is not None and (generation_id is not None or reopened.state != "absent"):
        return reopened.refusal
    resolved = legacy_comparison_resolution(config, contract, generation_id=generation_id)
    if isinstance(resolved, ReviewRefusal) or reopened.manifest is None:
        return resolved
    return replace(
        resolved,
        closed_leaf=ClosedLeafReview(
            reopened=reopened,
            sentence="This historical comparison preserves its recorded source and evidence; its canonical knowledge datasets are legacy-unavailable.",
        ),
    )


def closed_leaf_limitations(resolved: ReviewCandidateResolution) -> tuple[str, ...]:
    closed = resolved.closed_leaf
    if closed is None:
        return ()
    return (
        "history:recorded-comparison",
        f"history:comparison-generation:{closed.generation_id}",
        *(f"history:intent:{side}:legacy-unavailable" for side in ("before", "after")),
    )


def closed_leaf_intent_detail(resolved: ReviewCandidateResolution) -> str | None:
    return None if resolved.closed_leaf is None else resolved.closed_leaf.sentence


def closed_leaf_dataset_refusal(resolved: ReviewCandidateResolution) -> ReviewRefusal | None:
    if resolved.closed_leaf is None:
        return None
    return refusal(
        "candidate_dataset_absent",
        "the historical comparison's knowledge is legacy-unavailable; canonical datasets are retired",
        next_action="read its recorded source comparison; no current knowledge is substituted",
        offending_input=LEGACY_UNAVAILABLE,
    )

"""Bind review tree records to exact delivered code and memory trees (ICR-R21).

New writes use only MIK-R25's retained four-tree records. Historical generation JSON and v1
receipts remain readable for immutable source evidence; their missing memory-tree proof is explicit.
Receipts measure completed transactions and never gate closeout or integration.
"""

from __future__ import annotations

import hashlib
from dataclasses import dataclass
from pathlib import Path
from tempfile import TemporaryDirectory
from typing import Any, Literal

from pydantic import ValidationError

from agents_remember.application.review_comparison_generation import (
    ComparisonGenerationRef,
    generation_directories,
    read_generation_refs,
)
from agents_remember.application.review_tree_comparison import (
    comparison_directory,
    comparison_records,
)
from agents_remember.kernel.canonical_json import canonical_json_bytes, decoded_json
from agents_remember.memory.knowledge.durable_evidence import (
    DurableEvidencePublication,
    EvidenceReadBack,
    durable_reports_root,
    publish_durable_evidence,
    read_back_evidence,
)
from agents_remember.memory.knowledge.refusals import KnowledgeStorageError
from agents_remember.models.knowledge.review_final_output_receipt import (
    FINAL_OUTPUT_RECEIPT_VERSION,
    FINAL_OUTPUT_SELECTION_RULE,
    FinalOutputPhase,
    FinalOutputReceipt,
    LegacyFinalOutputReceipt,
    tree_comparison_digest,
    tree_match_state,
    tree_output_verdict,
)
from agents_remember.models.knowledge.review_trees import ReviewTreeComparisonRecord
from agents_remember.observer.events import now_iso
from agents_remember.worktrees import route_review
from agents_remember.worktrees.modules.git import require_git, worktree_candidate_tree
from agents_remember.worktrees.task_resolver import slugify
from agents_remember.worktrees.worktree_contract import WorktreeContract

FINAL_OUTPUT_RECEIPTS_PREFIX = "final-output"


@dataclass(frozen=True)
class ReviewComparisonSelection:
    state: Literal["selected", "no-comparison", "legacy-limit", "unreadable", "ambiguous"]
    leaf_id: str
    comparison: ReviewTreeComparisonRecord | None
    detail: str


def select_review_comparison(task_root: Path, leaf_id: str) -> ReviewComparisonSelection:
    """Select the highest retained tree-record number; never substitute a historical dataset."""

    directory = comparison_directory(task_root, leaf_id)
    records = comparison_records(task_root, leaf_id)
    paths = tuple(directory.glob("*.json")) if directory.is_dir() else ()
    if len(paths) != len(records) or any(
        record.task_id != task_root.name or record.leaf_id != leaf_id for record in records
    ):
        return ReviewComparisonSelection(
            "unreadable",
            leaf_id,
            None,
            "a retained tree comparison is unreadable or names a different task or leaf; no comparison is selected",
        )
    if records:
        latest = records[-1]
        tied = [record for record in records if record.number == latest.number]
        if len({tree_comparison_digest(record) for record in tied}) != 1:
            return ReviewComparisonSelection(
                "ambiguous",
                leaf_id,
                None,
                "different source records claim the highest tree comparison number; no comparison is selected",
            )
        return ReviewComparisonSelection(
            "selected",
            leaf_id,
            latest,
            f"tree comparison {latest.task_id}/{leaf_id}/{latest.number} has the highest recorded number",
        )
    if generation_directories(task_root, leaf_id):
        return ReviewComparisonSelection(
            "legacy-limit",
            leaf_id,
            None,
            "only historical dataset generations exist; they retain source identity but prove no exact memory candidate tree",
        )
    return ReviewComparisonSelection(
        "no-comparison", leaf_id, None, "no retained tree comparison exists for this leaf"
    )


def comparison_key(record: ReviewTreeComparisonRecord) -> str:
    return f"tree-{record.number}"


def source_comparison_matches(task_root: Path, record: ReviewTreeComparisonRecord) -> bool:
    """Check the complete embedded source record against the retained comparison, not its own seal."""

    return record.task_id == task_root.name and any(
        record == source for source in comparison_records(task_root, record.leaf_id)
    )


def require_comparison_repositories(
    contract: WorktreeContract, record: ReviewTreeComparisonRecord
) -> None:
    expected = (
        contract.code_repo_path,
        contract.code_repo_path,
        contract.memory_repo_path,
        contract.memory_repo_path,
    )
    actual = (record.code_base, record.code_candidate, record.memory_base, record.memory_candidate)
    if any(
        repository is None or Path(side.repository).resolve() != repository.resolve()
        for repository, side in zip(expected, actual, strict=True)
    ):
        raise ValueError(
            "the retained comparison repositories do not match this enclosure's code and memory repositories"
        )


@dataclass(frozen=True)
class FinalOutputReceiptPublication:
    publication: DurableEvidencePublication
    receipt: FinalOutputReceipt
    read_back: EvidenceReadBack


@dataclass(frozen=True)
class FinalOutputReceiptRead:
    state: Literal["recorded", "legacy-limit", "not-recorded", "unreadable"]
    leaf_id: str
    phase: FinalOutputPhase
    destination: Path
    receipt: FinalOutputReceipt | LegacyFinalOutputReceipt | None
    sha256: str | None
    superseded_by: tuple[ComparisonGenerationRef | ReviewTreeComparisonRecord, ...]
    detail: str


def receipt_file_name(leaf_id: str, generation_id: str, phase: FinalOutputPhase) -> str:
    return f"{FINAL_OUTPUT_RECEIPTS_PREFIX}-{slugify(leaf_id)}-{generation_id}-{phase}.json"


def record_final_output_receipt(
    contract: WorktreeContract,
    *,
    phase: FinalOutputPhase,
    code_commit: str,
    memory_content_commit: str,
) -> FinalOutputReceiptPublication:
    selection = select_review_comparison(contract.task_root, contract.leaf_id)
    if selection.comparison is None:
        raise RuntimeError(selection.detail)
    comparison = selection.comparison
    require_comparison_repositories(contract, comparison)
    code_tree = require_git(contract.code_repo_path, ["rev-parse", f"{code_commit}^{{tree}}"])
    memory_tree = (
        require_git(contract.memory_repo_path, ["rev-parse", f"{memory_content_commit}^{{tree}}"])
        if memory_content_commit and contract.memory_repo_path is not None
        else None
    )
    code_match = tree_match_state(comparison.code_candidate.tree, code_tree)
    memory_match = tree_match_state(comparison.memory_candidate.tree, memory_tree)
    receipt = FinalOutputReceipt(
        phase=phase,
        recorded_at=now_iso(),
        repository_id=contract.repo_name,
        master=contract.parent_task_name or contract.task_name,
        leaf_id=contract.leaf_id,
        task_root=str(contract.task_root),
        contract_path=str(contract.contract_path),
        comparison=comparison,
        comparison_digest=tree_comparison_digest(comparison),
        delivered_code_commit=code_commit,
        delivered_code_tree_id=code_tree,
        delivered_memory_content_commit=memory_content_commit if memory_tree else None,
        delivered_memory_tree_id=memory_tree,
        code_match=code_match,
        memory_match=memory_match,
        state=tree_output_verdict(code_match, memory_match),
    )
    publication = publish_durable_evidence(
        contract.task_root,
        receipt_file_name(contract.leaf_id, comparison_key(comparison), phase),
        canonical_json_bytes(receipt.model_dump(mode="json", by_alias=True)).decode("utf-8"),
    )
    return FinalOutputReceiptPublication(publication, receipt, read_back_evidence(publication))


def read_final_output_receipts(
    task_root: Path,
    leaf_id: str,
    generation_id: str,
    *,
    phases: tuple[FinalOutputPhase, ...] = ("closeout", "integration"),
) -> tuple[FinalOutputReceiptRead, ...]:
    return tuple(_read_receipt(task_root, leaf_id, generation_id, phase) for phase in phases)


def _read_receipt(
    task_root: Path, leaf_id: str, key: str, phase: FinalOutputPhase
) -> FinalOutputReceiptRead:
    destination = durable_reports_root(task_root) / receipt_file_name(leaf_id, key, phase)
    try:
        raw = destination.read_bytes()
    except FileNotFoundError:
        return FinalOutputReceiptRead(
            "not-recorded",
            leaf_id,
            phase,
            destination,
            None,
            None,
            (),
            f"no {phase} receipt is recorded at {destination}",
        )
    except OSError as error:
        return FinalOutputReceiptRead(
            "unreadable", leaf_id, phase, destination, None, None, (), str(error)
        )
    try:
        data = decoded_json(raw.decode("utf-8"))
        if not isinstance(data, dict):
            raise ValueError("a receipt must be a JSON object")
        if data.get("receipt_version") == "ar-review-final-output-receipt/v1":
            legacy = LegacyFinalOutputReceipt.model_validate(data)
            if legacy.leaf_id != leaf_id or legacy.phase != phase or legacy.generation_id != key:
                raise ValueError("the historical receipt names another leaf, phase or generation")
            return FinalOutputReceiptRead(
                "legacy-limit",
                leaf_id,
                phase,
                destination,
                legacy,
                hashlib.sha256(raw).hexdigest(),
                _historical_successors(task_root, leaf_id, key),
                "historical v1 receipt retains source and dataset identities but proves no exact reviewed memory tree; tree coverage is unavailable",
            )
        receipt = FinalOutputReceipt.model_validate(data)
        if (
            receipt.leaf_id != leaf_id
            or receipt.phase != phase
            or comparison_key(receipt.comparison) != key
            or not source_comparison_matches(task_root, receipt.comparison)
        ):
            raise ValueError(
                "the receipt does not describe the retained source comparison at this location"
            )
    except (UnicodeDecodeError, ValueError, ValidationError) as error:
        return FinalOutputReceiptRead(
            "unreadable", leaf_id, phase, destination, None, None, (), str(error)
        )
    successors = tuple(
        record
        for record in comparison_records(task_root, leaf_id)
        if record.number > receipt.comparison.number
    )
    return FinalOutputReceiptRead(
        "recorded",
        leaf_id,
        phase,
        destination,
        receipt,
        hashlib.sha256(raw).hexdigest(),
        successors,
        receipt.statement(),
    )


def _historical_successors(
    task_root: Path, leaf_id: str, generation_id: str
) -> tuple[ComparisonGenerationRef, ...]:
    """Retain the existing JSON-only supersession history without claiming memory-tree coverage."""

    refs = read_generation_refs(task_root, leaf_id)
    selected = next((ref for ref in refs if ref.generation_id == generation_id), None)
    if selected is None:
        return ()
    return tuple(ref for ref in refs if ref.generation_index > selected.generation_index)


def final_output_selection_block(
    contract: WorktreeContract,
    prepared_candidate_tree: str | None,
    prepared_memory_tree: str | None = None,
) -> dict[str, Any]:
    if contract.kind != "leaf":
        return {
            "state": "not-applicable",
            "detail": "a series contract owns no leaf tree comparison",
        }
    selection = select_review_comparison(contract.task_root, contract.leaf_id)
    record = selection.comparison
    block: dict[str, Any] = {
        "selection_version": "ar-review-final-comparison-selection/v2",
        "state": selection.state,
        "leaf_id": contract.leaf_id,
        "selection_rule": FINAL_OUTPUT_SELECTION_RULE,
        "comparison": None if record is None else record.model_dump(mode="json", by_alias=True),
        "comparison_digest": None if record is None else tree_comparison_digest(record),
        "prepared_candidate_code_tree_id": prepared_candidate_tree,
        "prepared_candidate_memory_tree_id": prepared_memory_tree,
        "prepared_code_is_reviewed_candidate": None,
        "prepared_memory_is_reviewed_candidate": None,
        "prepared_is_reviewed_candidate": None,
        "detail": selection.detail,
    }
    if record is None:
        return block
    try:
        require_comparison_repositories(contract, record)
    except ValueError as error:
        block.update(state="unreadable", detail=str(error))
        return block
    code = (
        None
        if prepared_candidate_tree is None
        else record.code_candidate.tree == prepared_candidate_tree
    )
    memory = (
        None
        if prepared_memory_tree is None
        else record.memory_candidate.tree == prepared_memory_tree
    )
    block.update(
        prepared_code_is_reviewed_candidate=code,
        prepared_memory_is_reviewed_candidate=memory,
        prepared_is_reviewed_candidate=False
        if False in (code, memory)
        else (True if code is True and memory is True else None),
    )
    return block


def attach_prepared_selection(
    payload: dict[str, Any], contract: WorktreeContract
) -> dict[str, Any]:
    if not payload.get("ok"):
        return payload
    prepared = route_review.code_candidate_tree(contract) if contract.kind == "leaf" else None
    memory = None
    memory_detail = "no memory candidate was captured"
    if contract.kind == "leaf" and contract.memory_worktree is not None:
        try:
            with TemporaryDirectory(prefix="ar-final-memory-") as scratch:
                memory = worktree_candidate_tree(contract.memory_worktree, Path(scratch) / "index")
                memory_detail = (
                    "the complete memory candidate was captured through an isolated index"
                )
        except (OSError, RuntimeError) as error:
            memory_detail = f"the prepared memory candidate could not be captured: {error}"
    payload["final_comparison_selection"] = final_output_selection_block(contract, prepared, memory)
    payload["final_comparison_selection"]["prepared_memory_detail"] = memory_detail
    return payload


def attach_closeout_receipt(payload: dict[str, Any], contract: WorktreeContract) -> dict[str, Any]:
    if payload.get("ok") and payload.get("code_commit"):
        payload["final_output_receipt"] = final_output_result_block(
            contract,
            phase="closeout",
            code_commit=str(payload["code_commit"]),
            memory_content_commit=str(payload.get("memory_content_commit") or ""),
        )
    return payload


def attach_integration_receipt(
    payload: dict[str, Any], contract: WorktreeContract
) -> dict[str, Any]:
    if payload.get("ok") and payload.get("integrated_code_commit"):
        payload["final_output_receipt"] = final_output_result_block(
            contract,
            phase="integration",
            code_commit=str(payload["integrated_code_commit"]),
            memory_content_commit=str(payload.get("integrated_memory_content_commit") or ""),
        )
    return payload


def final_output_result_block(
    contract: WorktreeContract,
    *,
    phase: FinalOutputPhase,
    code_commit: str,
    memory_content_commit: str,
) -> dict[str, Any]:
    if contract.kind != "leaf":
        return {
            "receipt_version": FINAL_OUTPUT_RECEIPT_VERSION,
            "state": "not-applicable",
            "phase": phase,
            "detail": "a series contract owns no leaf tree comparison",
        }
    selection = select_review_comparison(contract.task_root, contract.leaf_id)
    if selection.comparison is None:
        return {
            "receipt_version": FINAL_OUTPUT_RECEIPT_VERSION,
            "state": "not-recorded",
            "phase": phase,
            "leaf_id": contract.leaf_id,
            "selection_state": selection.state,
            "detail": selection.detail,
        }
    try:
        recorded = record_final_output_receipt(
            contract,
            phase=phase,
            code_commit=code_commit,
            memory_content_commit=memory_content_commit,
        )
    except (KnowledgeStorageError, ValidationError, OSError, RuntimeError, ValueError) as error:
        return {
            "receipt_version": FINAL_OUTPUT_RECEIPT_VERSION,
            "state": "not-recorded",
            "phase": phase,
            "leaf_id": contract.leaf_id,
            "detail": str(error),
        }
    block = recorded.receipt.model_dump(mode="json", by_alias=True)
    block.update(
        state="recorded",
        receipt_state=recorded.receipt.state,
        statement=recorded.receipt.statement(),
        destination=str(recorded.publication.destination),
        sha256=recorded.publication.sha256,
        replaced_existing_receipt=recorded.publication.replaced_existing,
        read_back=recorded.read_back.state,
    )
    return block

"""The reviewed identity's recorded governing-route associations (ICR-R08@v1), read from text.

A governing route is a recorded association like a realization and a family membership, and it is the
one the comparison's union does not carry as an item. This module reads it for one identity on each
snapshot and displays the recorded sides.

**Where it is read from (MIK-R26).** The canonical store's scalar join row between an identity and a
route is retired, and the derived index never projected it, so the old read answered ``ungoverned``
for every identity of a converted tree. The association is now read from the text: a family declares
its route set in its record file (the index's ``ix_route``). Each declared route is one recorded
association, so a family with several routes is displayed as one relationship per route, each naming
that one route; no value holds a list of routes. An invariant file declares no route, so an invariant
stays ``ungoverned`` exactly as before.

Four states are kept apart, and each is a fact rather than a default:

* ``recorded`` -- the snapshot records the identity and declares this route for it;
* ``ungoverned`` -- the snapshot records the identity and no route governs it. An ungoverned identity
  is not placed in the repository root and no route is inferred from the paths its claims name;
* ``not_recorded`` -- the snapshot does not record the identity at all, which is a different fact from
  an identity recorded with no route, so the existence question is asked by identity before the route
  question is;
* ``unavailable`` -- the snapshot records the family and its file carries no route declarations this
  read can ask, so whether a route governs it was not read. It is never rendered as ``ungoverned``:
  that would state a fact nobody read.

A route that only one snapshot declares, while the other snapshot is governed by other routes, is a
one-sided association (``added`` or ``retracted``). A snapshot that has no route of its own to show
contributes its state side instead, so an identity that became governed, or one a snapshot does not
record, is still displayed with both sides.

A review with no reviewed identity -- a path seed -- asks about no identity's route and is answered
with no association rather than with a route read for whichever record the path matched first.
"""

from __future__ import annotations

from collections.abc import Mapping
from dataclasses import dataclass
from typing import Literal

from agents_remember.application.review_recorded_relationships import RecordedSnapshot
from agents_remember.models.knowledge.read import KnowledgeReadSeed
from agents_remember.models.knowledge.review_relationships import (
    ReviewRelationshipGap,
    ReviewRelationshipMovement,
    ReviewRelationshipSide,
    ReviewRelationshipTransition,
)

__all__ = [
    "GOVERNING_ROUTE_KIND",
    "governing_route_movements",
]

GOVERNING_ROUTE_KIND: Literal["governing_route"] = "governing_route"

_IdentityKind = Literal["invariant", "family"]
_SideState = Literal["recorded", "ungoverned", "not_recorded", "unavailable"]

# The existence question a governing-route read needs first: a snapshot that does not hold the
# identity and a snapshot that holds it with no route are different facts, so the identity is asked
# for by itself, one statement per governed identity kind.
_IDENTITY_QUESTIONS: Mapping[str, str] = {
    "invariant": "SELECT 1 FROM invariant WHERE repository_id = ? AND invariant_id = ?",
    "family": "SELECT 1 FROM family WHERE repository_id = ? AND family_id = ?",
}

# The two index tables a family's route declarations are read through: the identifier mapping from
# the read's UUID to the record's text identifier, and the declared routes per family.
_ROUTE_TABLES = frozenset({"ix_uuid", "ix_route"})

# The gap each side state that is not an association is stated with.
_GAP_CODES: Mapping[str, Literal["route_not_recorded", "route_unavailable"]] = {
    "not_recorded": "route_not_recorded",
    "unavailable": "route_unavailable",
}

# --- the reviewed identity's governing routes -------------------------------------------------


def governing_route_movements(
    selector: KnowledgeReadSeed | None,
    repository_id: str,
    before: RecordedSnapshot,
    after: RecordedSnapshot,
) -> tuple[ReviewRelationshipMovement, ...]:
    """The reviewed identity's governing-route associations, one per route, or none when none is asked.

    A review with no reviewed identity -- a path seed, or the task-context composition -- asks about
    no identity's governing route, so none is displayed. That is a statement about the question, not
    about the repository: no root route and no guessed identity stands in for the one that was not
    named. An identity with no route on either snapshot is displayed as one movement whose two sides
    state that; otherwise each route either snapshot declares is one movement, in route order.
    """

    subject = _subject_identity(selector)
    if subject is None:
        return ()
    before_read = _read_side(before, repository_id, subject)
    after_read = _read_side(after, repository_id, subject)
    routes = sorted({*before_read.routes, *after_read.routes})
    if not routes:
        return (_movement(subject, before_read.state_side(), after_read.state_side()),)
    return tuple(
        _movement(subject, before_read.side_for(route), after_read.side_for(route))
        for route in routes
    )


def _subject_identity(selector: KnowledgeReadSeed | None) -> tuple[_IdentityKind, str] | None:
    """Return ``(identity kind, identity)`` for a selector that names one, or ``None``.

    A selector that names an identity -- or an exact revision of one -- asks about that identity's
    governing route. A path selector names no identity, so it is answered with no route association
    rather than with a route read for whichever record the path happened to match first.
    """

    kind = getattr(selector, "kind", None)
    if kind in ("invariant", "invariant_revision"):
        return ("invariant", str(selector.invariant_id))  # type: ignore[attr-defined]
    if kind in ("family", "family_revision"):
        return ("family", str(selector.family_id))  # type: ignore[attr-defined]
    return None


@dataclass(frozen=True)
class _SideRead:
    """What one snapshot states about one identity's governing routes."""

    side: Literal["before", "after"]
    record_kind: _IdentityKind
    record_id: str
    state: _SideState
    routes: tuple[str, ...] = ()

    def side_for(self, route: str) -> ReviewRelationshipSide | None:
        """This snapshot's side of one route's association, or ``None`` when it holds none.

        A snapshot governed by other routes simply does not hold this association, which is the
        one-sided case. A snapshot with no route to show states what it is instead.
        """

        if route in self.routes:
            return self._rendered(
                "recorded",
                f"the {self.side} snapshot governs {self.record_kind} {self.record_id} by its "
                f"declared route {route}",
                route,
            )
        if self.state == "recorded":
            return None
        return self.state_side()

    def state_side(self) -> ReviewRelationshipSide:
        """The side of a snapshot that declares no route for the identity, stating which fact it is."""

        if self.state == "not_recorded":
            return ReviewRelationshipSide(
                side=self.side,
                state="not_recorded",
                detail=(
                    f"the {self.side} snapshot records no {self.record_kind} {self.record_id}, so "
                    "it records no governing route for it; this is a different fact from an "
                    "identity recorded with no route, and neither is filled in from the other "
                    "snapshot"
                ),
            )
        if self.state == "unavailable":
            return self._rendered(
                "unavailable",
                f"the {self.side} snapshot records {self.record_kind} {self.record_id}, and its "
                "file carries no route declarations to read, so whether a route governs it was "
                "not read; this is not the fact that no route governs it",
            )
        return self._rendered(
            "ungoverned",
            f"the {self.side} snapshot records {self.record_kind} {self.record_id} with no "
            "governing route; an ungoverned identity is not placed in the repository root and no "
            "route is inferred from the paths its claims name",
        )

    def _rendered(
        self, state: _SideState, detail: str, route: str | None = None
    ) -> ReviewRelationshipSide:
        """One side about a recorded identity; a route's own path is its identity in the text."""

        return ReviewRelationshipSide(
            side=self.side,
            state=state,
            relationship_id=route,
            record_kind=self.record_kind,
            record_id=self.record_id,
            route_id=route,
            route_path=route,
            detail=detail,
        )


def _read_side(
    snapshot: RecordedSnapshot, repository_id: str, subject: tuple[_IdentityKind, str]
) -> _SideRead:
    """Read what one snapshot states about one identity's governing routes."""

    record_kind, record_id = subject
    side: Literal["before", "after"] = "before" if snapshot.side == "before" else "after"
    if not _identity_recorded(snapshot, repository_id, record_kind, record_id):
        return _SideRead(side, record_kind, record_id, "not_recorded")
    if record_kind == "invariant":
        # An invariant file declares no route, whatever tables the snapshot's file carries.
        return _SideRead(side, record_kind, record_id, "ungoverned")
    if not _route_tables_present(snapshot):
        return _SideRead(side, record_kind, record_id, "unavailable")
    routes = _declared_routes(snapshot, record_id)
    return _SideRead(side, record_kind, record_id, "recorded" if routes else "ungoverned", routes)


def _declared_routes(snapshot: RecordedSnapshot, family_id: str) -> tuple[str, ...]:
    """The route set one family record declares in this snapshot's text, in route order."""

    texts = [
        str(row[0])
        for row in snapshot.connection.execute(
            "SELECT id FROM ix_uuid WHERE uuid = ?", (family_id,)
        )
    ]
    return tuple(
        sorted(
            {
                str(row[0])
                for text in texts
                for row in snapshot.connection.execute(
                    "SELECT route FROM ix_route WHERE family = ?", (text,)
                )
            }
        )
    )


def _route_tables_present(snapshot: RecordedSnapshot) -> bool:
    """Whether the snapshot's file carries the tables a family's route declarations are read from."""

    names = {
        str(row[0])
        for row in snapshot.connection.execute(
            "SELECT name FROM sqlite_master WHERE type = 'table' AND name IN ('ix_uuid', 'ix_route')"
        )
    }
    return names == _ROUTE_TABLES


def _movement(
    subject: tuple[_IdentityKind, str],
    before_side: ReviewRelationshipSide | None,
    after_side: ReviewRelationshipSide | None,
) -> ReviewRelationshipMovement:
    """Display one governing-route association with the side each snapshot states for it."""

    record_kind, record_id = subject
    transition = _route_transition(before_side, after_side)
    two_sided = before_side is not None and after_side is not None
    return ReviewRelationshipMovement(
        relationship_kind=GOVERNING_ROUTE_KIND,
        record_kind=record_kind,
        record_id=record_id,
        transition=transition,
        before=() if before_side is None else (before_side,),
        after=after_side,
        # Both sides are one association: a governing route of the identity this review selected,
        # read on each snapshot. The basis names that, so the movement states why its two sides are
        # one rather than asserting a movement. A route only one snapshot declares paired nothing.
        pairing_basis="same_governed_identity" if two_sided else None,
        gaps=_route_gaps(before_side, after_side),
        statement=_route_statement(subject, before_side, after_side, transition),
    )


def _route_transition(
    before_side: ReviewRelationshipSide | None, after_side: ReviewRelationshipSide | None
) -> ReviewRelationshipTransition:
    """Name what happened to one association between the two snapshots.

    A comparison with a side whose route declarations were not read measured nothing and says so;
    it is never ``unchanged``, even when both sides are unreadable.
    """

    if before_side is None:
        return "added"
    if after_side is None:
        return "retracted"
    if "unavailable" in (before_side.state, after_side.state):
        return "unresolved"
    return "unchanged" if before_side.state == after_side.state else "moved"


def _route_gaps(
    before_side: ReviewRelationshipSide | None, after_side: ReviewRelationshipSide | None
) -> tuple[ReviewRelationshipGap, ...]:
    """One gap per displayed side that could not state whether a route governs the identity."""

    return tuple(
        ReviewRelationshipGap(
            side=side.side,
            field="route",
            code=_GAP_CODES[side.state],
            detail=side.detail,
        )
        for side in (before_side, after_side)
        if side is not None and side.state in _GAP_CODES
    )


def _route_statement(
    subject: tuple[_IdentityKind, str],
    before_side: ReviewRelationshipSide | None,
    after_side: ReviewRelationshipSide | None,
    transition: ReviewRelationshipTransition,
) -> str:
    """State the route association on the displayed sides, and what the difference between them is."""

    record_kind, record_id = subject
    if before_side is None or after_side is None:
        return _one_sided_statement(subject, before_side or after_side)
    before_word = _route_word(record_kind, before_side)
    after_word = _route_word(record_kind, after_side)
    if transition == "unchanged":
        return (
            f"the {record_kind} {record_id} is associated with the same governing route on both "
            f"snapshots ({before_word})"
        )
    if transition == "unresolved":
        return (
            f"the {record_kind} {record_id} records {before_word} on the baseline and {after_word} "
            "on the candidate; a side whose route declarations were not read cannot be compared, "
            "so no movement of the governing-route association is stated"
        )
    return (
        f"the {record_kind} {record_id} records {before_word} on the baseline and {after_word} on "
        "the candidate, so the governing-route association moved; both recorded sides are displayed"
    )


def _one_sided_statement(
    subject: tuple[_IdentityKind, str], held: ReviewRelationshipSide | None
) -> str:
    """State a route that one snapshot declares while the other is governed by other routes."""

    record_kind, record_id = subject
    assert held is not None, "a governing-route movement displays at least one side"
    holder, other = (
        ("baseline", "candidate") if held.side == "before" else ("candidate", "baseline")
    )
    return (
        f"the {record_kind} {record_id} declares the governing route {held.route_path} on the "
        f"{holder} and not on the {other}, which governs it by other routes; this one recorded "
        "side is displayed"
    )


def _route_word(record_kind: str, side: ReviewRelationshipSide) -> str:
    """Name one side's route association in one phrase, for a sentence about both sides."""

    if side.state == "recorded":
        return f"route {side.route_path}"
    if side.state == "ungoverned":
        return "no governing route"
    if side.state == "unavailable":
        return "route declarations that were not read"
    return f"no {record_kind} identity recorded"


def _identity_recorded(
    snapshot: RecordedSnapshot, repository_id: str, record_kind: str, record_id: str
) -> bool:
    """Whether one snapshot records one identity row at all."""

    statement = _IDENTITY_QUESTIONS[record_kind]
    return (
        next(iter(snapshot.connection.execute(statement, (repository_id, record_id))), None)
        is not None
    )

"""Measure the exact post-sync code and memory candidates against one retained tree comparison.

The sync transaction is already complete: missing comparison/capture/evidence is a result state,
never an admission gate. Historical v1 measurements are readable but prove no memory-tree coverage.
"""

from __future__ import annotations

import hashlib
from dataclasses import dataclass
from pathlib import Path
from tempfile import TemporaryDirectory
from typing import Any, Literal

from agents_remember.application.review_comparison_generation import (
    ComparisonGenerationManifest,
)
from agents_remember.application.review_final_output_receipt import (
    comparison_key,
    require_comparison_repositories,
    select_review_comparison,
    source_comparison_matches,
)
from agents_remember.errors import FutureCodeCandidateError
from agents_remember.kernel.canonical_json import canonical_json_bytes, decoded_json
from agents_remember.memory.knowledge.durable_evidence import (
    DurableEvidencePublication,
    EvidenceReadBack,
    durable_reports_root,
    publish_durable_evidence,
    read_back_evidence,
)
from agents_remember.memory.knowledge.refusals import KnowledgeStorageError
from agents_remember.models.knowledge.review_final_output_receipt import tree_comparison_digest
from agents_remember.models.knowledge.review_sync_rebinding import (
    REVIEW_SYNC_REBINDING_VERSION,
    LegacyReviewSyncRebinding,
    ReviewSyncRebinding,
    code_channel_match,
    tree_sync_verdict,
)
from agents_remember.models.knowledge.review_trees import ReviewTreeComparisonRecord
from agents_remember.observer.events import now_iso
from agents_remember.worktrees.modules.future_code_candidate import capture_future_code_candidate
from agents_remember.worktrees.modules.git import head_commit, worktree_candidate_tree
from agents_remember.worktrees.task_resolver import slugify
from agents_remember.worktrees.worktree_contract import WorktreeContract

REVIEW_SYNC_REBINDINGS_PREFIX = "review-sync-rebinding"
_SUPERSESSION_ACTION = "Open and record a successor tree comparison for the resolved code and memory candidates; retain this source comparison as previous input."

_CARRYING_SYNC_STATES: frozenset[str] = frozenset(
    {
        "synced",
        "sync-pass-completed-memory-skipped",
        "sync-pass-completed-source-moved-again",
    }
)

# The states in which the transaction resolved no pair, each with the store fact it observed and the
# R22 reason no rebinding is recorded. A table rather than a ladder, and one entry per state, so the
# sentence a caller reads names the state it was actually given: "this result is not a completed
# sync" was false for several of these, and it is the master's ruled-blocking class.
_CARRIED_NOTHING: dict[str, tuple[str, str]] = {
    "would-sync": (
        "preview",
        "this is a preview: the sync read its sources and moved no ref, no branch and no journal, so "
        "it resolved no pair to measure the review against",
    ),
    "already-current": (
        "no-movement",
        "the recorded base pair and participating work branches already contained the official line, "
        "so this sync carried nothing and resolved no pair to measure the review against",
    ),
    "sync-resolution-required": (
        "not-resolved",
        "the sync stopped with unmerged paths the knowledge adapter would not settle, so no pair was "
        "resolved to measure the review against",
    ),
    "sync-cancelled": (
        "cancelled",
        "the explicit cancellation restored every participating branch, so no pair was resolved to "
        "measure the review against",
    ),
    "memory-sync-choice-required": (
        "choice-required",
        "the sync required a memory sync choice before any mutation, so no pair was resolved to "
        "measure the review against",
    ),
}


def resolved_pair_completed(payload: dict[str, Any]) -> bool:
    """Whether this result is a finished sync that **carried the official line** into the leaf.

    Three facts, and each is checked rather than inferred: the operation is the sync, the sync did not
    fail, and its state is one of the three in which the transaction carried the line
    (:data:`_CARRYING_SYNC_STATES`). Nothing is inferred from which keys the payload happens to hold
    -- a preview is excluded because ``would-sync`` is not a carrying state, and an up-to-date leaf is
    excluded because ``already-current`` reports that the pair *already* held the line rather than
    that anything was carried. Every other state is described by its own entry in
    :data:`_CARRIED_NOTHING`, so a caller is told which fact was observed instead of a blanket claim
    about completions.

    The success conjunct is carried even though every producer of those three states returns zero
    today: a carrying state reported beside ``ok: false`` is a result this tool must not measure, and
    stating the requirement here is what keeps that true of a producer that does not exist yet.

    Exported because two callers need the same answer: the recorder, and the block that says why
    nothing was bound.
    """

    return (
        payload.get("operation") == "worktree_sync"
        and bool(payload.get("ok"))
        and str(payload.get("state", "")) in _CARRYING_SYNC_STATES
    )


@dataclass(frozen=True)
class ReviewSyncRebindingPublication:
    publication: DurableEvidencePublication
    rebinding: ReviewSyncRebinding
    read_back: EvidenceReadBack


@dataclass(frozen=True)
class ReviewSyncRebindingRead:
    state: Literal["recorded", "legacy-limit", "not-recorded", "unreadable"]
    leaf_id: str
    generation_id: str
    destination: Path
    rebinding: ReviewSyncRebinding | LegacyReviewSyncRebinding | None
    sha256: str | None
    detail: str

    def covers_resolved_pair(self) -> bool:
        return (
            isinstance(self.rebinding, ReviewSyncRebinding)
            and self.rebinding.covers_resolved_pair()
        )


def rebinding_file_name(leaf_id: str, generation_id: str) -> str:
    return f"{REVIEW_SYNC_REBINDINGS_PREFIX}-{slugify(leaf_id)}-{generation_id}.json"


class _ResolvedSourceUnmeasurable(RuntimeError):
    pass


def record_review_sync_rebinding(
    contract: WorktreeContract, payload: dict[str, Any]
) -> ReviewSyncRebindingPublication | None:
    if not resolved_pair_completed(payload) or contract.kind != "leaf":
        return None
    selection = select_review_comparison(contract.task_root, contract.leaf_id)
    if selection.comparison is None:
        return None
    comparison = selection.comparison
    require_comparison_repositories(contract, comparison)
    try:
        resolved = capture_future_code_candidate(contract)
    except FutureCodeCandidateError as error:
        raise _ResolvedSourceUnmeasurable(f"{error.status}: {error}") from error
    memory_head, memory_tree, memory_detail = _resolved_memory(contract)
    code_match = code_channel_match(comparison.code_candidate.tree, resolved.codeCandidateTree)
    memory_match = (
        "unmeasured"
        if memory_tree is None
        else code_channel_match(comparison.memory_candidate.tree, memory_tree)
    )
    rebinding = ReviewSyncRebinding(
        recorded_at=now_iso(),
        repository_id=contract.repo_name,
        master=contract.parent_task_name or contract.task_name,
        leaf_id=contract.leaf_id,
        task_root=str(contract.task_root),
        contract_path=str(contract.contract_path),
        comparison=comparison,
        comparison_digest=tree_comparison_digest(comparison),
        resolved_code_head=resolved.observedCodeHead,
        resolved_candidate_code_tree_id=resolved.codeCandidateTree,
        resolved_memory_head=memory_head,
        resolved_candidate_memory_tree_id=memory_tree,
        memory_detail=memory_detail,
        code_match=code_match,
        memory_match=memory_match,
        state=tree_sync_verdict(code_match, memory_match),
        successor_action=_SUPERSESSION_ACTION,
    )
    publication = publish_durable_evidence(
        contract.task_root,
        rebinding_file_name(contract.leaf_id, comparison_key(comparison)),
        canonical_json_bytes(rebinding.model_dump(mode="json", by_alias=True)).decode("utf-8"),
    )
    return ReviewSyncRebindingPublication(publication, rebinding, read_back_evidence(publication))


def _resolved_memory(contract: WorktreeContract) -> tuple[str | None, str | None, str]:
    if contract.memory_worktree is None:
        return None, None, "the enclosure has no memory worktree to capture"
    try:
        before = head_commit(contract.memory_worktree)
        with TemporaryDirectory(prefix="ar-sync-memory-") as scratch:
            tree = worktree_candidate_tree(contract.memory_worktree, Path(scratch) / "index")
        if before != head_commit(contract.memory_worktree):
            return None, None, "memory HEAD moved during the isolated candidate capture"
        return (
            before,
            tree,
            "the complete memory candidate was captured through an isolated copy of its index",
        )
    except (OSError, RuntimeError) as error:
        return None, None, f"the memory candidate could not be captured: {error}"


def rebinding_result_block(contract: WorktreeContract, payload: dict[str, Any]) -> dict[str, Any]:
    try:
        published = record_review_sync_rebinding(contract, payload)
    except _ResolvedSourceUnmeasurable as error:
        payload["review_rebinding"] = {
            "rebinding_version": REVIEW_SYNC_REBINDING_VERSION,
            "state": "source-unmeasured",
            "covers_resolved_pair": False,
            "detail": str(error),
        }
        return payload
    except (KnowledgeStorageError, OSError, RuntimeError, ValueError) as error:
        payload["review_rebinding"] = {
            "rebinding_version": REVIEW_SYNC_REBINDING_VERSION,
            "state": "not-recorded",
            "covers_resolved_pair": False,
            "detail": str(error),
        }
        return payload
    if published is None:
        payload["review_rebinding"] = _nothing_to_bind_block(contract, payload)
        payload["review_rebinding"]["rebinding_version"] = REVIEW_SYNC_REBINDING_VERSION
        return payload
    block = published.rebinding.model_dump(mode="json", by_alias=True)
    block.update(
        covers_resolved_pair=published.rebinding.covers_resolved_pair(),
        statement=published.rebinding.statement(),
        evidence=published.publication.reference(),
        evidence_sha256=published.publication.digest(),
        read_back=published.read_back.state,
    )
    payload["review_rebinding"] = block
    return payload


def _nothing_to_bind_block(contract: WorktreeContract, payload: dict[str, Any]) -> dict[str, Any]:
    if payload.get("operation") != "worktree_sync" or contract.kind != "leaf":
        return {
            "state": "not-applicable",
            "covers_resolved_pair": False,
            "detail": "this result is not a managed sync of a leaf's pair",
        }
    if not resolved_pair_completed(payload):
        state = str(payload.get("state", ""))
        if payload.get("ok") or state not in _CARRYING_SYNC_STATES:
            reason = _CARRIED_NOTHING.get(state)
            if reason is not None:
                return {"state": reason[0], "detail": reason[1], "covers_resolved_pair": False}
        return {
            "state": "not-measured",
            "covers_resolved_pair": False,
            "detail": f"sync state {state!r} did not successfully carry a resolved pair",
        }
    selection = select_review_comparison(contract.task_root, contract.leaf_id)
    return {
        "state": selection.state,
        "selection_state": selection.state,
        "detail": selection.detail,
        "covers_resolved_pair": False,
    }


def read_review_sync_rebinding(
    task_root: Path, leaf_id: str, generation_id: str
) -> ReviewSyncRebindingRead:
    destination = durable_reports_root(task_root) / rebinding_file_name(leaf_id, generation_id)
    try:
        raw = destination.read_bytes()
    except FileNotFoundError:
        return ReviewSyncRebindingRead(
            "not-recorded",
            leaf_id,
            generation_id,
            destination,
            None,
            None,
            f"no rebinding is recorded at {destination}",
        )
    except OSError as error:
        return ReviewSyncRebindingRead(
            "unreadable", leaf_id, generation_id, destination, None, None, str(error)
        )
    try:
        data = decoded_json(raw.decode("utf-8"))
        if not isinstance(data, dict):
            raise ValueError("a rebinding must be a JSON object")
        if data.get("rebinding_version") == "ar-review-sync-rebinding/v1":
            legacy = LegacyReviewSyncRebinding.model_validate(data)
            if legacy.leaf_id != leaf_id or legacy.supersedes_generation_id != generation_id:
                raise ValueError("the historical rebinding names another leaf or generation")
            return ReviewSyncRebindingRead(
                "legacy-limit",
                leaf_id,
                generation_id,
                destination,
                legacy,
                f"sha256:{hashlib.sha256(raw).hexdigest()}",
                "historical v1 rebinding retains source and dataset identities but proves no exact reviewed memory tree; pair coverage is unavailable",
            )
        rebinding = ReviewSyncRebinding.model_validate(data)
        if (
            rebinding.leaf_id != leaf_id
            or comparison_key(rebinding.comparison) != generation_id
            or not source_comparison_matches(task_root, rebinding.comparison)
        ):
            raise ValueError(
                "the rebinding does not describe the retained source comparison at this location"
            )
    except (UnicodeDecodeError, ValueError) as error:
        return ReviewSyncRebindingRead(
            "unreadable", leaf_id, generation_id, destination, None, None, str(error)
        )
    return ReviewSyncRebindingRead(
        "recorded",
        leaf_id,
        generation_id,
        destination,
        rebinding,
        f"sha256:{hashlib.sha256(raw).hexdigest()}",
        rebinding.statement(),
    )


def rebinding_names_the_generation(
    read: ReviewSyncRebindingRead,
    manifest: ComparisonGenerationManifest | ReviewTreeComparisonRecord,
) -> ReviewSyncRebinding | None:
    """Accept only an exact tree-bound source record; legacy dataset proof cannot cover memory."""

    if not isinstance(manifest, ReviewTreeComparisonRecord) or not isinstance(
        read.rebinding, ReviewSyncRebinding
    ):
        return None
    return read.rebinding if read.rebinding.comparison == manifest else None

"""Read-only index connections, pinned index schema creation, and schema inspection."""

from __future__ import annotations

from collections.abc import Sequence
from pathlib import Path

import apsw

from agents_remember.memory.knowledge import schema_generations
from agents_remember.memory.knowledge.refusals import KnowledgeStorageError
from agents_remember.models.knowledge.context import KnowledgeSchemaIdentity

# The bounded lock policy: wait this long for a competing writer, then refuse as busy rather
# than block indefinitely. The operation never retries against a re-read snapshot.
BUSY_TIMEOUT_MILLISECONDS = 1000


def open_read_only_database(database_path: Path) -> apsw.Connection:
    """Open one existing database through a connection that cannot write it.

    Verification uses this on purpose. A pass that could repair the file it is checking would
    prove only that the repair worked, and a snapshot whose identity is confirmed by a writable
    connection is not confirmed by a reader. ``foreign_keys`` is not set here because no
    statement this connection runs writes a row.
    """

    connection = apsw.Connection(str(database_path), flags=apsw.SQLITE_OPEN_READONLY)
    connection.execute(f"PRAGMA busy_timeout={BUSY_TIMEOUT_MILLISECONDS}")
    return connection


def fetch_one(
    connection: apsw.Connection,
    statement: str,
    parameters: Sequence[str | int | float | bytes | None] = (),
) -> tuple[object, ...] | None:
    """Return the one row a query selects, or ``None`` when it selects nothing.

    Every reader in this package asks the same question -- the row, if there is one -- and one
    owner for it keeps the "iterate once, then check for a row" shape identical everywhere
    instead of repeated at each call site.
    """

    row = next(iter(connection.execute(statement, tuple(parameters))), None)
    return None if row is None else tuple(row)


def create_or_validate_schema(connection: apsw.Connection) -> KnowledgeSchemaIdentity:
    """Create the newest supported generation on an empty database, else validate what is there.

    Initialization **declares** a generation; it does not select one. An empty database has no
    version to read, so "never from the running build" cannot govern this path: creating a store
    declares the newest generation this build supports, through one explicit constant. Validation
    is registry-driven thereafter, so an existing database of any registered generation is accepted
    and checked against *its own* tables, columns and triggers.
    """

    if next(iter(connection.execute("SELECT count(*) FROM sqlite_schema WHERE type = 'table'")))[0]:
        return inspect_schema(connection)
    declared = schema_generations.generation_of_new_store()
    with immediate_transaction(connection):
        for statement in schema_generations.create_schema_statements(declared):
            connection.execute(statement)
    # The version marker is written after the DDL commits. A crash between the two leaves a
    # complete but unversioned database, which the next open refuses instead of guessing -- the
    # opposite order could leave a database that claims a generation it does not have.
    connection.execute(f"PRAGMA user_version = {declared.user_version}")
    return inspect_schema(connection)


def inspect_schema(connection: apsw.Connection) -> KnowledgeSchemaIdentity:
    """Validate an existing database against the generation the database itself declares.

    The generation is selected from ``PRAGMA user_version`` and resolved against the registry --
    never against the running build. A dataset whose version is not registered is refused as an
    unsupported schema; it is not migrated, repaired or re-read under another generation. A dataset
    that resolves to a registered generation whose structure it does not match is refused by the
    structural checks below, not by a fallback to a different generation.
    """

    declared = schema_generations.generation_of_database(connection)
    _require_declared_tables(connection, declared)
    _require_declared_triggers(connection, declared)
    return KnowledgeSchemaIdentity(
        schema_name=declared.schema_name,
        user_version=declared.user_version,
        fingerprint=declared.fingerprint,
    )


def immediate_transaction(connection: apsw.Connection) -> _ImmediateTransaction:
    """Open one immediate transaction: the write lock is taken before the first read."""

    return _ImmediateTransaction(connection)


class _ImmediateTransaction:
    """A single immediate transaction whose exit rolls back on any failure.

    ``__exit__`` never suppresses the exception: the rollback happens here and the caller still
    sees the failure it caused.
    """

    def __init__(self, connection: apsw.Connection) -> None:
        self._connection = connection

    def __enter__(self) -> None:
        self._connection.execute("BEGIN IMMEDIATE")

    def __exit__(self, *exception: object) -> None:
        if exception and exception[0] is not None:
            self._connection.execute("ROLLBACK")
            return
        self._connection.execute("COMMIT")


def _require_declared_tables(
    connection: apsw.Connection, declared: schema_generations.SchemaGeneration
) -> None:
    present = {
        str(row[0])
        for row in connection.execute("SELECT name FROM sqlite_schema WHERE type = 'table'")
    }
    missing = [name for name in declared.tables if name not in present]
    if missing:
        raise KnowledgeStorageError(
            f"unsupported schema: missing canonical table(s) {', '.join(missing)}. The index "
            "cannot answer its declared queries with a partial schema."
        )
    for table, columns in declared.columns.items():
        actual = tuple(str(row[1]) for row in connection.execute(f"PRAGMA table_info({table})"))
        if actual != columns:
            raise KnowledgeStorageError(
                f"unsupported schema: table {table} declares columns {actual}, expected {columns}"
            )


def _require_declared_triggers(
    connection: apsw.Connection, declared: schema_generations.SchemaGeneration
) -> None:
    present = {
        str(row[0])
        for row in connection.execute("SELECT name FROM sqlite_schema WHERE type = 'trigger'")
    }
    missing = sorted(set(declared.triggers) - present)
    if missing:
        raise KnowledgeStorageError(
            f"unsupported schema: missing immutability trigger(s) {', '.join(missing)}. A "
            "database without them can rewrite a sealed revision, so it is not this schema."
        )

"""The family reads: family identity and sealed family revisions.

A family is a stable subject whose revision carries an authored joint guarantee about a set of
invariant revisions. A family revision is one sealed aggregate -- the guarantee, the origin state,
the acceptance reference, the provenance and the sorted predecessor set -- and every read
re-derives the stored revision's payload seal on the way out.

These functions only read. The rows come from the derived index of a memory tree
(:mod:`agents_remember.memory.knowledge_index.projection`); the database write path was retired
with the canonical database (MIK-R26).
"""

from __future__ import annotations

from typing import TYPE_CHECKING

from agents_remember.memory.knowledge import records
from agents_remember.memory.knowledge.connection import fetch_one
from agents_remember.models.knowledge.family import (
    FamilyIdentity,
    StoredFamilyRevision,
)

if TYPE_CHECKING:
    from agents_remember.memory.knowledge.store import OpenedKnowledgeStore


_FAMILY_COLUMNS = "repository_id, family_id, display_label, label_provenance"

_FAMILY_REVISION_COLUMNS = (
    "repository_id, family_id, revision_id, display_version, joint_guarantee, state_at_origin, "
    "acceptance_ref, provenance, payload_digest"
)


def get_family(store: OpenedKnowledgeStore, family_id: str) -> FamilyIdentity | None:
    """Return one family identity, or ``None`` when it is not in this namespace."""

    row = fetch_one(
        store.connection,
        f"SELECT {_FAMILY_COLUMNS} FROM family WHERE repository_id = ? AND family_id = ?",
        (store.repository_id, family_id),
    )
    return None if row is None else records.decode_family_row(row)


def get_family_revision(
    store: OpenedKnowledgeStore, revision_id: str
) -> StoredFamilyRevision | None:
    """Return one family revision aggregate, verifying its stored seal before returning it."""

    row = fetch_one(
        store.connection,
        f"SELECT {_FAMILY_REVISION_COLUMNS} FROM family_revision "
        "WHERE repository_id = ? AND revision_id = ?",
        (store.repository_id, revision_id),
    )
    if row is None:
        return None
    return records.decode_family_revision_row(
        row, _family_predecessors(store, str(row[1]), revision_id)
    )


def list_family_revision_ids(store: OpenedKnowledgeStore, family_id: str) -> tuple[str, ...]:
    """Return every revision identity of one family, in stable order."""

    return tuple(
        str(row[0])
        for row in store.connection.execute(
            "SELECT revision_id FROM family_revision "
            "WHERE repository_id = ? AND family_id = ? ORDER BY revision_id",
            (store.repository_id, family_id),
        )
    )


def _family_predecessors(
    store: OpenedKnowledgeStore, family_id: str, revision_id: str
) -> tuple[str, ...]:
    return records.decode_predecessor_rows(
        list(
            store.connection.execute(
                "SELECT parent_revision_id FROM family_predecessor "
                "WHERE repository_id = ? AND family_id = ? AND child_revision_id = ?",
                (store.repository_id, family_id, revision_id),
            )
        )
    )


__all__ = [
    "get_family",
    "get_family_revision",
    "list_family_revision_ids",
]

"""One opened knowledge dataset: its namespace, its validated schema and its read methods.

The dataset a reader opens is the derived index of a memory tree (MIK-R23): an SQLite file with the
store's schema, built from the tree's text files and never written by this module. The store reads
a repository's identities and revisions and re-derives each stored revision's payload seal on the
way out. Family and membership reads live in :mod:`families` and :mod:`memberships`; they take
this store as their first argument.

**No writer of knowledge rows is here.** The insert operations of the canonical database -- the
invariant, revision, family, membership, anchor and realization writers -- were retired with it
(MIK-R26 rule 4). :func:`open_existing_knowledge_store` and :func:`open_read_only_store` open
through a connection that cannot write.

"""

from __future__ import annotations

from dataclasses import dataclass
from pathlib import Path
from typing import Literal

import apsw

from agents_remember.memory.knowledge import logical, records
from agents_remember.memory.knowledge.connection import (
    inspect_schema,
    open_read_only_database,
)
from agents_remember.memory.knowledge.refusals import (
    KnowledgeStorageError,
)
from agents_remember.memory.knowledge.schema_generations import (
    SchemaGeneration,
    generation_for_name,
)
from agents_remember.models.knowledge.candidate import SnapshotIdentity
from agents_remember.models.knowledge.context import KnowledgeSchemaIdentity
from agents_remember.models.knowledge.family import FamilyIdentity
from agents_remember.models.knowledge.invariant import (
    InvariantIdentity,
    StoredInvariantRevision,
)
from agents_remember.models.knowledge.repository import RepositoryIdentity

_REVISION_COLUMNS = (
    "repository_id, invariant_id, revision_id, display_version, statement, applicability, "
    "conditions, exclusions, state_at_origin, acceptance_ref, provenance, payload_digest"
)


@dataclass(frozen=True)
class OpenedKnowledgeStore:
    """One opened store: its bound namespace, its validated schema and its connection."""

    database_path: Path
    repository_id: str
    schema: KnowledgeSchemaIdentity
    connection: apsw.Connection

    @property
    def generation(self) -> SchemaGeneration:
        """Resolve the pinned index schema the validated file declares.

        Row readers use its table and column manifest; this store never creates or migrates a schema.
        """

        resolved = generation_for_name(self.schema.schema_name)
        if resolved is None:
            raise KnowledgeStorageError(
                f"the store is open under schema {self.schema.schema_name!r}, which is not a "
                "generation this build supports"
            )
        return resolved

    def __enter__(self) -> OpenedKnowledgeStore:
        return self

    def __exit__(self, *exception: object) -> Literal[False]:
        """Close on every exit, including a failure raised inside the block."""

        del exception
        self.close()
        return False

    # -- lifecycle -----------------------------------------------------------------

    def close(self) -> None:
        """Close this owned read handle; cache files remain with the index cache's cleanup owner."""

        self.connection.close()

    # -- identity ------------------------------------------------------------------

    def get_repository(self) -> RepositoryIdentity | None:
        """Return the bound namespace, or ``None`` when the store has no repository row."""

        row = next(
            iter(
                self.connection.execute(
                    "SELECT repository_id, authority_home FROM repository WHERE repository_id = ?",
                    (self.repository_id,),
                )
            ),
            None,
        )
        return None if row is None else records.decode_repository_row(row)

    def get_invariant(self, invariant_id: str) -> InvariantIdentity | None:
        """Return one invariant identity, or ``None`` when it is not in this namespace."""

        row = next(
            iter(
                self.connection.execute(
                    "SELECT repository_id, invariant_id, display_label, label_provenance "
                    "FROM invariant WHERE repository_id = ? AND invariant_id = ?",
                    (self.repository_id, invariant_id),
                )
            ),
            None,
        )
        return None if row is None else records.decode_invariant_row(row)

    def list_invariants(self) -> tuple[InvariantIdentity, ...]:
        """Return every invariant identity this namespace records, in stable order.

        The Intent Reviewer's subject is one of these identities, and a reader that must be handed
        a subject before it can list the candidates cannot enumerate a candidate it was not pointed
        at. The order is the identity's own column, so two runs over one snapshot agree without a
        tiebreak this reader chose.
        """

        return tuple(
            records.decode_invariant_row(row)
            for row in self.connection.execute(
                "SELECT repository_id, invariant_id, display_label, label_provenance "
                "FROM invariant WHERE repository_id = ? ORDER BY invariant_id",
                (self.repository_id,),
            )
        )

    def list_families(self) -> tuple[FamilyIdentity, ...]:
        """Return every family identity this namespace records, in stable order.

        The same enumeration as :meth:`list_invariants`, for the surface's other admitted subject
        kind. A family identity is the second thing the reviewer can be opened on, so both lists
        are read the same way rather than one being derived from the other.
        """

        return tuple(
            records.decode_family_row(row)
            for row in self.connection.execute(
                "SELECT repository_id, family_id, display_label, label_provenance "
                "FROM family WHERE repository_id = ? ORDER BY family_id",
                (self.repository_id,),
            )
        )

    def get_revision(self, revision_id: str) -> StoredInvariantRevision | None:
        """Return one revision aggregate with its decoded predecessor set, or ``None``."""

        row = next(
            iter(
                self.connection.execute(
                    f"SELECT {_REVISION_COLUMNS} FROM invariant_revision "
                    "WHERE repository_id = ? AND revision_id = ?",
                    (self.repository_id, revision_id),
                )
            ),
            None,
        )
        if row is None:
            return None
        return records.decode_revision_row(row, self._predecessors_of(str(row[1]), revision_id))

    # -- index identity -------------------------------------------------------------

    def snapshot_identity(self) -> SnapshotIdentity:
        """Return this index's logical identity, as stored right now.

        The caller resolves a context from this value and later compares the two inside one
        transaction, which is what makes "the dataset I read" a checked precondition rather than a
        remembered one.
        """

        repository = self.get_repository()
        if repository is None:
            raise KnowledgeStorageError(
                f"the candidate database is not bound to repository namespace {self.repository_id}"
            )
        return logical.snapshot_identity(self.connection, repository, self.generation)

    # -- internals ------------------------------------------------------------------

    def _predecessors_of(self, invariant_id: str, revision_id: str) -> tuple[str, ...]:
        return records.decode_predecessor_rows(
            list(
                self.connection.execute(
                    "SELECT parent_revision_id FROM invariant_predecessor "
                    "WHERE repository_id = ? AND invariant_id = ? AND child_revision_id = ?",
                    (self.repository_id, invariant_id, revision_id),
                )
            )
        )


def open_existing_knowledge_store(database_path: Path, repository_id: str) -> OpenedKnowledgeStore:
    """Open an existing dataset for reading, without creating, repairing or writing it.

    The same open as :func:`open_read_only_store`, under the name the reviewer's readers call: the
    datasets they open are index files, which nothing but the index builder writes.
    """

    return open_read_only_store(database_path, repository_id)


def open_read_only_store(database_path: Path, repository_id: str) -> OpenedKnowledgeStore:
    """Open one existing dataset through a connection that cannot write it.

    The connection is :func:`…connection.open_read_only_database`, whose strongest available
    statement is a ``SELECT``, and the schema is validated against the generation the *file*
    declares. A caller therefore cannot reach a writable handle by accident. The returned store is
    closed by the caller.
    """

    path = Path(database_path)
    if not path.exists():
        raise KnowledgeStorageError(f"the knowledge index does not exist: {path}")
    connection = open_read_only_database(path)
    return OpenedKnowledgeStore(
        database_path=path,
        repository_id=repository_id,
        schema=inspect_schema(connection),
        connection=connection,
    )

"""Durable closeout Git-intent publication and crash reconciliation."""

from __future__ import annotations

import hashlib
import tempfile
from pathlib import Path
from typing import cast

from agents_remember.kernel.git_command import (
    IsolatedGitState,
    copy_git_index,
    run_git,
    run_git_with_isolated_index_and_objects,
)
from agents_remember.kernel.memory_ledger import MEMORY_CACHE_EXCLUDE
from agents_remember.models.closeout.input import EffectiveCloseoutInput
from agents_remember.models.lifecycles.mutation_evidence import (
    CloseoutMutationLeg,
    GitMutationEvidence,
    GitMutationSnapshot,
)
from agents_remember.models.lifecycles.operation import (
    LifecycleOperationRecord,
)
from agents_remember.worktrees.modules.args import WorktreeArgs, report_operation_progress
from agents_remember.worktrees.modules.git import (
    head_commit,
    require_git,
    worktree_candidate_tree,
)
from agents_remember.worktrees.worktree_contract import WorktreeContract, load_contract

CLEAN_STATUS_FINGERPRINT = hashlib.sha256(b"").hexdigest()


def snapshot_is_clean(snapshot: GitMutationSnapshot) -> bool:
    """Whether index, candidate, and status all describe the exact current HEAD."""
    return snapshot_is_clean_at_head(snapshot, snapshot.head)


def snapshot_is_clean_at_head(
    snapshot: GitMutationSnapshot,
    expected_head: str,
) -> bool:
    """Whether ``snapshot`` is clean at one expected commit identity."""
    return (
        snapshot.head,
        snapshot.indexTree,
        snapshot.candidateTree,
        snapshot.statusFingerprint,
    ) == (
        expected_head,
        snapshot.contentHeadTree or snapshot.headTree,
        snapshot.contentHeadTree or snapshot.headTree,
        CLEAN_STATUS_FINGERPRINT,
    )


def initial_closeout_mutation_evidence(
    contract: WorktreeContract,
    effective_input: EffectiveCloseoutInput,
) -> dict[CloseoutMutationLeg, GitMutationEvidence]:
    """Create pre-mutation cells for exactly the enabled repository legs."""
    repositories = _contract_repositories(contract)
    evidence: dict[CloseoutMutationLeg, GitMutationEvidence] = {}
    for leg in ("code", "memory"):
        if not effective_input.enabled(leg):
            continue
        repository = cast(Path, repositories[leg])
        accepted = git_mutation_snapshot(
            repository,
            contract.worktree_group / "reports" / f".{leg}-admission.index",
            memory_cache=leg == "memory",
        )
        evidence[leg] = GitMutationEvidence(
            leg=leg,
            repository=repository.as_posix(),
            acceptedBefore=accepted,
        )
    return evidence


def begin_git_mutation(
    args: WorktreeArgs,
    *,
    leg: CloseoutMutationLeg,
    repository: Path,
    expected_output_tree: str | None,
    use_current_candidate: bool = False,
) -> GitMutationEvidence:
    """Persist exact pre-command facts before a commit command can launch."""
    _require_mutation_leg_authority(args, leg, repository)
    before = git_mutation_snapshot(
        repository, _evidence_index_path(args, leg), memory_cache=leg == "memory"
    )
    return _publish_mutation_intent(
        args,
        leg=leg,
        repository=repository,
        before=before,
        expected_output_tree=(
            before.candidateTree if use_current_candidate else expected_output_tree
        ),
    )


def _publish_mutation_intent(
    args: WorktreeArgs,
    *,
    leg: CloseoutMutationLeg,
    repository: Path,
    before: GitMutationSnapshot,
    expected_output_tree: str | None,
) -> GitMutationEvidence:
    evidence = GitMutationEvidence(
        leg=leg,
        repository=repository.as_posix(),
        state="mutation-intent",
        acceptedBefore=_accepted_prestate(args, leg),
        before=before,
        expectedOutputTree=expected_output_tree,
    )
    _report_evidence(args, evidence)
    return evidence


def _require_isolated_git(
    repository: Path,
    arguments: list[str],
    *,
    state: IsolatedGitState,
    input_text: str | None = None,
) -> str:
    result = run_git_with_isolated_index_and_objects(
        repository,
        arguments,
        state=state,
        input_text=input_text,
    )
    if result.returncode != 0:
        raise RuntimeError("isolated Git mutation evidence operation failed")
    return result.stdout.strip()


def _accepted_prestate(
    args: WorktreeArgs,
    leg: CloseoutMutationLeg,
) -> GitMutationSnapshot | None:
    if args.contract_path is None or not args.operation_key:
        return None
    contract = load_contract(args.contract_path)
    from agents_remember.worktrees.integration.lifecycle.lifecycle_operation_location import (  # noqa: PLC0415
        located_lifecycle_operation_store,
    )

    for kind in ("closeout", "direct-landing"):
        record = located_lifecycle_operation_store(contract, kind).read()
        if record is not None and record.operationKey == args.operation_key:
            evidence = record.mutationEvidence.get(leg)
            return evidence.acceptedBefore if evidence is not None else None
    return None


def prove_git_commit(
    args: WorktreeArgs,
    evidence: GitMutationEvidence,
    *,
    repository: Path,
    commit: str,
) -> None:
    """Publish a commit hash only after Git output matches the bound tree."""
    _require_mutation_leg_authority(args, evidence.leg, repository)
    _require_evidence_repository(evidence, repository)
    if evidence.before is None:
        raise RuntimeError("closeout mutation proof requires pre-command Git evidence")
    actual = git_mutation_snapshot(
        repository, _evidence_index_path(args, evidence.leg), memory_cache=evidence.leg == "memory"
    )
    expected_tree = evidence.expectedOutputTree
    if expected_tree is None or not commit_matches_intent(
        repository,
        before=evidence.before,
        actual=actual,
        expected_tree=expected_tree,
        commit=commit,
    ):
        raise RuntimeError(
            f"closeout {evidence.leg} commit does not match its mutation-intent ref/tree"
        )
    _report_evidence(
        args,
        evidence.model_copy(
            update={"state": "commit-proven", "observed": actual, "commit": commit}
        ),
    )


def reconcile_closeout_mutations(
    record: LifecycleOperationRecord,
    *,
    temporary_indices: bool = False,
) -> dict[CloseoutMutationLeg, GitMutationEvidence]:
    """Resolve launched-without-hash attempts without guessing from HEAD alone."""
    _require_record_repositories(record)
    reconciled = dict(record.mutationEvidence)
    for leg, evidence in record.mutationEvidence.items():
        if (
            evidence.state != "mutation-intent"
            or evidence.before is None
            or evidence.observed is not None
        ):
            continue
        try:
            repository = Path(evidence.repository)
            actual = _reconciliation_snapshot(
                record,
                leg,
                repository,
                temporary_index=temporary_indices,
            )
            if actual == evidence.before:
                reconciled[leg] = evidence.model_copy(
                    update={"state": "reconciled-unchanged", "observed": actual}
                )
                continue
            expected_tree = evidence.expectedOutputTree
            if expected_tree is None or actual.head == evidence.before.head:
                # Prepared or dirty intermediate state is live recovery evidence,
                # not a durable mutation-cell transition.  Leaving the intent
                # untouched lets the same generation finish and publish the first
                # durable output proof after a crash.
                continue
            if commit_matches_intent(
                repository,
                before=evidence.before,
                actual=actual,
                expected_tree=expected_tree,
                commit=actual.head,
            ):
                reconciled[leg] = evidence.model_copy(
                    update={
                        "state": "commit-proven",
                        "observed": actual,
                        "commit": actual.head,
                    }
                )
            else:
                # Conflicting live state is reported by the typed recovery path;
                # it must not freeze an ambiguous observation into the intent.
                continue
        except (OSError, RuntimeError):
            # Missing or unreadable facts remain ambiguous and same-generation.
            continue
    return reconciled


def _reconciliation_snapshot(
    record: LifecycleOperationRecord,
    leg: CloseoutMutationLeg,
    repository: Path,
    *,
    temporary_index: bool,
) -> GitMutationSnapshot:
    if not temporary_index:
        return git_mutation_snapshot(
            repository, _record_index_path(record, leg), memory_cache=leg == "memory"
        )
    return ephemeral_git_mutation_snapshot(repository, memory_cache=leg == "memory")


def closeout_requires_recovery(record: LifecycleOperationRecord) -> bool:
    """Whether closeout evidence forbids replacement or cancellation."""
    return any(
        evidence.state in {"mutation-intent", "commit-proven"}
        for evidence in record.mutationEvidence.values()
    )


def git_mutation_snapshot(
    repository: Path, index_path: Path, *, memory_cache: bool = False
) -> GitMutationSnapshot:
    if memory_cache:
        return ephemeral_git_mutation_snapshot(repository, memory_cache=True)
    status_result = run_git(repository, ["status", "--porcelain=v1", "-z"])
    if status_result.returncode != 0:
        raise RuntimeError("Git status mutation evidence is unreadable")
    status = status_result.stdout
    head_ref = require_git(repository, ["symbolic-ref", "--quiet", "HEAD"])
    return GitMutationSnapshot(
        headRef=head_ref,
        head=head_commit(repository),
        headTree=require_git(repository, ["rev-parse", "HEAD^{tree}"]),
        refLogFingerprint=_ref_log_fingerprint(repository, head_ref),
        indexTree=require_git(repository, ["write-tree"]),
        candidateTree=worktree_candidate_tree(repository, index_path),
        statusFingerprint=hashlib.sha256(status.encode("utf-8")).hexdigest(),
    )


def ephemeral_git_mutation_snapshot(
    repository: Path, *, memory_cache: bool = False
) -> GitMutationSnapshot:
    """Read the exact snapshot through disposable index and object storage."""

    status_args = ["status", "--porcelain=v1", "-z"]
    if memory_cache:
        status_args.extend(["--", ".", ":(top,exclude)memory.md"])
    status_result = run_git(repository, ["--no-optional-locks", *status_args])
    if status_result.returncode != 0:
        raise RuntimeError("Git status mutation evidence is unreadable")
    head_ref = require_git(repository, ["symbolic-ref", "--quiet", "HEAD"])
    head = head_commit(repository)
    head_tree = require_git(repository, ["rev-parse", "HEAD^{tree}"])
    common_dir = Path(
        require_git(
            repository,
            ["rev-parse", "--path-format=absolute", "--git-common-dir"],
        )
    )
    source_index = Path(
        require_git(
            repository,
            ["rev-parse", "--path-format=absolute", "--git-path", "index"],
        )
    )
    with tempfile.TemporaryDirectory(prefix="ar-mutation-snapshot-") as temp_dir:
        root = Path(temp_dir)
        index_path = root / "index"
        if source_index.exists():
            # The copy keeps the index file's time, so a file rewritten in the second the index
            # was written is still compared by content (:func:`copy_git_index`).
            copy_git_index(source_index, index_path)
        execution = IsolatedGitState(index_path, root / "objects", common_dir / "objects")
        content_head_tree = None
        if memory_cache:
            head_execution = IsolatedGitState(
                root / "head-index", root / "objects", common_dir / "objects"
            )
            _require_isolated_git(repository, ["read-tree", head_tree], state=head_execution)
            _exclude_cache_from_index(repository, head_execution)
            content_head_tree = _require_isolated_git(
                repository, ["write-tree"], state=head_execution
            )
        if not source_index.exists():
            _require_isolated_git(repository, ["read-tree", head_tree], state=execution)
        if memory_cache:
            _exclude_cache_from_index(repository, execution)
        index_tree = _require_isolated_git(repository, ["write-tree"], state=execution)
        add_args = ["add", "-A"]
        if memory_cache:
            add_args.extend(["--", ".", MEMORY_CACHE_EXCLUDE])
        _require_isolated_git(repository, add_args, state=execution)
        if memory_cache:
            _exclude_cache_from_index(repository, execution)
        candidate_tree = _require_isolated_git(repository, ["write-tree"], state=execution)
    return GitMutationSnapshot(
        headRef=head_ref,
        head=head,
        headTree=head_tree,
        contentHeadTree=content_head_tree,
        refLogFingerprint=_ref_log_fingerprint(repository, head_ref),
        indexTree=index_tree,
        candidateTree=candidate_tree,
        statusFingerprint=hashlib.sha256(status_result.stdout.encode("utf-8")).hexdigest(),
    )


def _exclude_cache_from_index(repository: Path, execution: IsolatedGitState) -> None:
    _require_isolated_git(
        repository, ["update-index", "--force-remove", "--", "memory.md"], state=execution
    )


def _ref_log_fingerprint(repository: Path, head_ref: str) -> str:
    """Bind the latest entry and bounded append identity of the exact branch log."""
    reflog_result = run_git(
        repository,
        ["reflog", "show", "-1", "--format=%H%x00%gD%x00%gs", head_ref],
    )
    if reflog_result.returncode != 0 or not reflog_result.stdout:
        raise RuntimeError("Git ref-log mutation evidence is unreadable")
    log_path = Path(
        require_git(
            repository,
            ["rev-parse", "--path-format=absolute", "--git-path", f"logs/{head_ref}"],
        )
    )
    facts = log_path.stat()
    identity = (
        f"{facts.st_dev}\0{facts.st_ino}\0{facts.st_size}\0{facts.st_mtime_ns}\0"
        f"{reflog_result.stdout}"
    )
    return hashlib.sha256(identity.encode("utf-8")).hexdigest()


def commit_matches_intent(
    repository: Path,
    *,
    before: GitMutationSnapshot,
    actual: GitMutationSnapshot,
    expected_tree: str,
    commit: str,
) -> bool:
    if (
        actual.headRef != before.headRef
        or actual.head != commit
        or actual.headTree != expected_tree
    ):
        return False
    return require_git(repository, ["rev-parse", f"{commit}^"]) == before.head


def _report_evidence(args: WorktreeArgs, evidence: GitMutationEvidence) -> None:
    report_operation_progress(
        args,
        f"{evidence.leg}-commit",
        current_command=f"{evidence.leg} Git mutation {evidence.state}",
        mutation_evidence=evidence.model_dump(mode="json"),
    )


def _evidence_index_path(args: WorktreeArgs, leg: CloseoutMutationLeg) -> Path:
    contract_path = cast(Path, args.contract_path)
    return contract_path.parent / "reports" / f".{leg}-mutation-evidence.index"


def _record_index_path(record: LifecycleOperationRecord, leg: CloseoutMutationLeg) -> Path:
    return Path(record.contractPath).parent / "reports" / f".{leg}-reconcile.index"


def _require_record_repositories(record: LifecycleOperationRecord) -> None:
    contract = load_contract(Path(record.contractPath))
    expected = _contract_repositories(contract)
    for leg, evidence in record.mutationEvidence.items():
        repository = expected[leg]
        if repository is None or Path(evidence.repository).resolve() != repository.resolve():
            raise RuntimeError(
                f"closeout {leg} mutation evidence repository is outside contract authority"
            )


def _require_mutation_leg_authority(
    args: WorktreeArgs,
    leg: CloseoutMutationLeg,
    repository: Path,
) -> None:
    effective = args.closeout_input
    if effective is None or not effective.enabled(leg):
        raise RuntimeError(f"closeout {leg} mutation leg is not enabled")
    if args.contract_path is None:
        raise RuntimeError("closeout mutation evidence requires a contract path")
    expected = _contract_repositories(load_contract(args.contract_path))[leg]
    if expected is None or expected.resolve() != repository.resolve():
        raise RuntimeError(f"closeout {leg} mutation repository is outside contract authority")


def _require_evidence_repository(
    evidence: GitMutationEvidence,
    repository: Path,
) -> None:
    if Path(evidence.repository).resolve() != repository.resolve():
        raise RuntimeError(f"closeout {evidence.leg} mutation repository changed after intent")


def _contract_repositories(
    contract: WorktreeContract,
) -> dict[CloseoutMutationLeg, Path | None]:
    return {
        "code": contract.code_worktree if contract.kind == "leaf" else None,
        "memory": contract.memory_worktree or contract.memory_repo_path,
    }

