_ACTIVE_PHASES = {
    "running-code",
    "code-resolution-required",
    "running-memory",
    "memory-resolution-required",
    "finalizing",
    "cancelling",
}

# The parked candidate's path sample kept in the journal. It is the proof set the restore
# re-checks per path; the exact count is journaled alongside it.
WIP_PATH_SAMPLE_LIMIT = 128


def sync_contract_under_authority(
    contract: WorktreeContract,
    args: WorktreeArgs,
    *,
    fetch: dict[str, object],
) -> WorktreeCommandResult:
    """Start, observe, continue, cancel, or recover one exact sync transaction.

    No lock is held across the call: an agent resolves retained conflicts in the
    ordinary worktree between calls.
    """

    try:
        invalid = sync_input_refusal(args, fetch)
        if invalid is not None:
            return invalid
        store = SyncOperationStore(contract.worktree_group)
        observed = _read_sync_record(contract, args, store, fetch)
        if isinstance(observed, WorktreeCommandResult):
            return observed
        return _route_sync_record(contract, args, store, observed, fetch)
    except (OSError, RuntimeError, ValueError) as error:
        return command_result(
            2,
            "sync-operation-refused",
            f"Sync could not prove a safe transition ({type(error).__name__}).",
            fetch,
            detail=str(error),
        )


def _read_sync_record(
    contract: WorktreeContract,
    args: WorktreeArgs,
    store: SyncOperationStore,
    fetch: dict[str, object],
) -> SyncOperationRecord | WorktreeCommandResult | None:
    try:
        record = store.read()
    except SyncJournalReadError as error:
        return recover_unreadable_journal(
            contract,
            args,
            store=store,
            error=error,
            fetch=fetch,
        )
    if record is None and authority_refs_exist(contract):
        return recover_missing_journal(
            contract,
            cancel=args.resolution_action == "cancel",
            dry_run=args.dry_run,
            store=store,
            fetch=fetch,
        )
    if isinstance(record, SyncQuarantineRecord):
        return quarantine_replay(args, record, fetch) if args.resolution_action else None
    if record is None:
        return None
    try:
        require_record_contract(contract, record)
    except SyncGitProofError:
        return recover_unreadable_journal(
            contract,
            args,
            store=store,
            error=store.semantic_read_error("journal-identity-invalid"),
            fetch=fetch,
        )
    return record


def _route_sync_record(
    contract: WorktreeContract,
    args: WorktreeArgs,
    store: SyncOperationStore,
    record: SyncOperationRecord | None,
    fetch: dict[str, object],
) -> WorktreeCommandResult:
    if record is not None and record.phase in _ACTIVE_PHASES:
        return _resume_active(contract, args, store, record, fetch)
    if record is not None and not args.dry_run:
        cleanup_terminal_residue(store, record)
    if args.resolution_action is None:
        return _admit_and_run(contract, args, store, record, fetch)
    if record is not None:
        return terminal_resolution_replay(contract, args, record, fetch)
    return command_result(
        2,
        "sync-resolution-not-active",
        "No active sync resolution exists for this contract.",
        fetch,
    )


def sync_input_refusal(
    args: WorktreeArgs,
    fetch: dict[str, object],
) -> WorktreeCommandResult | None:
    """Reject untyped/direct-call inputs before refs, selection, or Git can move."""

    if args.memory_sync_choice not in {None, "merge-memory", "skip-memory"}:
        return command_result(
            2,
            "sync-input-invalid",
            "memory_sync_choice must be exactly 'merge-memory' or 'skip-memory'.",
            fetch,
            invalidField="memory_sync_choice",
        )
    if args.resolution_action not in {None, "continue", "cancel"}:
        return command_result(
            2,
            "sync-input-invalid",
            "resolution_action must be exactly 'continue' or 'cancel'. Knowledge is text: a "
            "conflicted knowledge file is resolved in the worktree and staged, then continued.",
            fetch,
            invalidField="resolution_action",
        )
    return None


def _admit_and_run(
    contract: WorktreeContract,
    args: WorktreeArgs,
    store: SyncOperationStore,
    predecessor: SyncOperationRecord | None,
    fetch: dict[str, object],
) -> WorktreeCommandResult:
    code_tip, memory_tip, external = source_pair(contract)
    code = side_record(contract, "code", code_tip)
    memory = side_record(contract, "memory", memory_tip) if external else None
    current = _already_current_result(
        contract,
        code,
        memory,
        fetch,
    )
    if current is not None:
        return current
    if memory is not None and memory.plan == "merge" and args.memory_sync_choice is None:
        return memory_choice_required(contract, code, memory, fetch)
    if memory is not None and args.memory_sync_choice == "skip-memory":
        memory = memory.model_copy(update={"plan": "skip"})
    prepared = _admit_participating_sides(contract, code, memory, args, fetch)
    if isinstance(prepared, WorktreeCommandResult):
        return prepared
    code, memory = prepared
    record = _new_sync_record(contract, args, predecessor, code, memory)
    pin_authority(record)
    store.write(record)
    for side in (record.code, record.memory):
        if side is not None and side.temporary and side.plan not in {"already-current", "skip"}:
            ensure_temporary_worktree(side)
    return _run_automatic(contract, store, record, fetch)


def _cutover_locked(
    memory: SyncSideRecord | None, fetch: dict[str, object]
) -> WorktreeCommandResult | None:
    """MIK-R09 rule 6: a memory sync between unconverted sides waits for the crossing sync.

    It refuses, before anything moves, only when no side (own, incoming and, for a merge, their
    base) holds the layout marker and the repository holds converted memory elsewhere. A crossing
    sync -- some side converted -- is never refused, and a code-only sync (``skip-memory``) is not
    a memory sync.
    """

    if memory is None or memory.plan in {"already-current", "skip"}:
        return None
    repository = Path(memory.repository)
    sides = [memory.preSyncHead, memory.sourceCommit]
    try:
        if memory.plan == "merge":
            sides.append(merge_base(repository, *sides))  # a series side has no worktree yet
        if any(has_layout_marker(repository, side) for side in sides):
            return None
    except (LayoutProbeError, CrossingSyncError) as error:
        refusal: str | None = (
            "worktree_sync refuses: it cannot tell whether a memory side holds the layout marker "
            f"({error}), and an unanswered probe is never read as unconverted memory"
        )
    else:
        refusal = cutover_lock_refusal(
            repository,
            operation="worktree_sync",
            line=f"{memory.workBranch} ({memory.worktree})",
        )
    if refusal is None:
        return None
    return command_result(
        2,
        f"sync-{CUTOVER_LOCK_CODE}",
        "The memory sync is refused: its memory is unconverted and must cross the boundary first.",
        fetch,
        detail=refusal,
    )


def _admit_participating_sides(
    contract: WorktreeContract,
    code: SyncSideRecord,
    memory: SyncSideRecord | None,
    args: WorktreeArgs,
    fetch: dict[str, object],
) -> tuple[SyncSideRecord, SyncSideRecord | None] | WorktreeCommandResult:
    """Refuse, preview, or park: everything that precedes the journaled admission."""

    preflight = _cutover_locked(memory, fetch) or _preflight_participating_sides(
        code, memory, fetch
    )
    if preflight is not None:
        return preflight
    if args.dry_run:
        return sync_preview(code, memory, fetch)
    return _park_participating_wip(contract, code, memory, fetch)


def _side_parks_wip(side: SyncSideRecord | None) -> bool:
    """Only a live worktree this transaction will actually move parks its candidate."""

    return side is not None and not side.temporary and side.plan not in {"already-current", "skip"}


def _park_participating_wip(
    contract: WorktreeContract,
    code: SyncSideRecord,
    memory: SyncSideRecord | None,
    fetch: dict[str, object],
) -> tuple[SyncSideRecord, SyncSideRecord | None] | WorktreeCommandResult:
    """Stash each dirty moving side's candidate into the transaction that will return it.

    The parked identity is journaled with the admission record, so the candidate a closeout
    leaves in its worktree is never lost to the carry. A stash that genuinely cannot be
    taken restores whatever was already parked and refuses with the typed sync refusal.
    """

    parked: dict[SyncSide, SyncSideRecord] = {}
    for side in (code, memory):
        if not _side_parks_wip(side):
            continue
        assert side is not None
        paths = worktree_dirty_paths(side)
        if not paths:
            continue
        try:
            stash = park_worktree_wip(
                side,
                message=_wip_stash_message(contract, side),
            )
        except SyncGitProofError as error:
            detail = _restore_already_parked(parked, error)
            return command_result(2, "sync-side-preflight-failed", detail, fetch)
        parked[side.side] = side.model_copy(
            update={
                "wipState": "parked",
                "wipStash": stash,
                "wipPaths": paths[:WIP_PATH_SAMPLE_LIMIT],
                "wipPathCount": len(paths),
            }
        )
    return parked.get("code", code), parked.get("memory", memory)


def _wip_stash_message(contract: WorktreeContract, side: SyncSideRecord) -> str:
    """A stash message a human can find: the operation, the side, and the exact contract."""

    return (
        f"agents-remember worktree_sync parked {side.side} WIP for {contract.task_id} "
        f"({contract.contract_path.as_posix()})"
    )


def _restore_already_parked(
    parked: dict[SyncSide, SyncSideRecord], error: SyncGitProofError
) -> str:
    """Undo a partial park before refusing, so no candidate is left without a journal."""

    stranded: list[str] = []
    for side in parked.values():
        try:
            state, conflicts = apply_parked_wip(side)
            if state != "applied" or conflicts:
                stranded.append(f"{side.side} ({side.wipStash})")
                continue
            drop_parked_wip(side)
        except SyncGitProofError:
            stranded.append(f"{side.side} ({side.wipStash})")
    detail = str(error)
    if stranded:
        detail = (
            f"{detail} The parked candidate remains in refs/stash for "
            f"{', '.join(stranded)}; recover it with git stash apply."
        )
    return detail


def _already_current_result(
    contract: WorktreeContract,
    code: SyncSideRecord,
    memory: SyncSideRecord | None,
    fetch: dict[str, object],
) -> WorktreeCommandResult | None:
    """Report a pair whose recorded base and work branches already carry the source.

    A memory branch that already descends from its source is current whatever its
    ``memory.md`` says: the ledger is derived state, its rebuild reports the rows it
    cannot resolve, and this surface does not keep a second copy of that judgement.
    """

    bases_current = code.sourceCommit == contract.code_base_commit and (
        memory is None or memory.sourceCommit == contract.memory_base_commit
    )
    branches_current = code.plan == "already-current" and (
        memory is None or memory.plan == "already-current"
    )
    if not (bases_current and branches_current):
        return None
    return command_result(
        0,
        "already-current",
        "The recorded base pair and participating work branches contain the official line.",
        fetch,
    )


def _new_sync_record(
    contract: WorktreeContract,
    args: WorktreeArgs,
    predecessor: SyncOperationRecord | None,
    code: SyncSideRecord,
    memory: SyncSideRecord | None,
) -> SyncOperationRecord:
    generation = predecessor.generation + 1 if predecessor is not None else 1
    stamp = operation_stamp()
    return SyncOperationRecord(
        generation=generation,
        contractPath=contract.contract_path.resolve(strict=False).as_posix(),
        taskId=contract.task_id,
        contractKind=sync_contract_kind(contract),
        codeBaseFrom=contract.code_base_commit,
        memoryBaseFrom=contract.memory_base_commit,
        phase="running-code",
        memorySyncChoice=args.memory_sync_choice,
        code=code,
        memory=memory,
        createdAt=stamp,
        updatedAt=stamp,
    )


def _preflight_participating_sides(
    code: SyncSideRecord,
    memory: SyncSideRecord | None,
    fetch: dict[str, object],
) -> WorktreeCommandResult | None:
    """Refuse only the moving sides whose candidate genuinely cannot be parked."""

    for side in (code, memory):
        if side is None or side.temporary or side.plan in {"already-current", "skip"}:
            continue
        try:
            require_side_checkout(side)
            _require_parkable_worktree(side)
        except SyncGitProofError as error:
            return command_result(2, "sync-side-preflight-failed", str(error), fetch)
    return None


def _require_parkable_worktree(side: SyncSideRecord) -> None:
    """A dirty moving side is parked; only an unsettleable index or worktree is refused."""

    conflicts = content_conflicts(side)
    if conflicts:
        raise SyncGitProofError(
            f"{side.side} sync cannot park a worktree with unmerged paths: "
            f"{', '.join(conflicts[:30])}"
        )
    if merge_head(Path(side.worktree)) is not None:
        raise SyncGitProofError(f"{side.side} has an active merge outside sync admission")


def _resume_active(
    contract: WorktreeContract,
    args: WorktreeArgs,
    store: SyncOperationStore,
    record: SyncOperationRecord,
    fetch: dict[str, object],
) -> WorktreeCommandResult:
    require_pinned_authority(
        record,
        allow_expected_missing=record.phase == "finalizing",
    )
    if args.memory_sync_choice is not None and args.memory_sync_choice != record.memorySyncChoice:
        return manual_repair_result(
            "sync-input-mismatch",
            "memory_sync_choice cannot change after sync admission.",
            record,
            fetch,
        )
    if args.dry_run:
        return _active_preview(args, record, fetch)
    return _resume_live(contract, args, store, record, fetch)


def _active_preview(
    args: WorktreeArgs,
    record: SyncOperationRecord,
    fetch: dict[str, object],
) -> WorktreeCommandResult:
    if args.resolution_action == "cancel":
        return cancel_preview(record, fetch)
    if args.resolution_action != "continue":
        return active_preview(record, fetch)
    if record.phase in {"code-resolution-required", "memory-resolution-required"}:
        side = _retained_side(record)
        if side.wipState == "restore-conflict":
            return parked_wip_validation_preview(side, fetch)
        return resolution_validation_preview(side, fetch)
    return manual_repair_result(
        "sync-resolution-not-required",
        "The active transaction has no retained conflict to continue.",
        record,
        fetch,
    )


def _resume_live(
    contract: WorktreeContract,
    args: WorktreeArgs,
    store: SyncOperationStore,
    record: SyncOperationRecord,
    fetch: dict[str, object],
) -> WorktreeCommandResult:
    if args.resolution_action == "cancel" or record.phase == "cancelling":
        return cancel_sync(contract, store, record, fetch)
    if args.resolution_action == "continue":
        return _continue_resolution(contract, store, record, fetch)
    if record.phase in {"code-resolution-required", "memory-resolution-required"}:
        return resolution_required(record, fetch)
    return _run_automatic(contract, store, record, fetch)


def _run_automatic(
    contract: WorktreeContract,
    store: SyncOperationStore,
    record: SyncOperationRecord,
    fetch: dict[str, object],
) -> WorktreeCommandResult:
    try:
        record = _reconcile_completed_sides(store, record)
        if record.phase == "running-code":
            record = _run_side(store, record, "code")
            if record.phase == "code-resolution-required":
                return resolution_required(record, fetch)
        if record.phase == "running-memory":
            record = _run_side(store, record, "memory")
            if record.phase == "memory-resolution-required":
                return resolution_required(record, fetch)
        if record.phase == "finalizing":
            return finalize_sync(contract, store, record, fetch)
    except SyncKnowledgeValidationError as error:
        return _knowledge_validation_refused(error, record, fetch)
    except SyncGitProofError as error:
        return manual_repair_result("sync-git-proof-failed", str(error), record, fetch)
    return manual_repair_result(
        "sync-state-unrecognized",
        f"Sync stopped in unsupported phase {record.phase!r}.",
        record,
        fetch,
    )


def _run_side(
    store: SyncOperationStore,
    record: SyncOperationRecord,
    side_name: SyncSide,
) -> SyncOperationRecord:
    side = record.code if side_name == "code" else record.memory
    if side is None or side.plan in {"already-current", "skip"}:
        if side is not None and side_branch_head(side) != side.preSyncHead:
            raise SyncGitProofError(f"{side.side} work branch moved after sync admission")
        completed = (
            side.model_copy(update={"state": "completed", "resultHead": side.preSyncHead})
            if side is not None
            else None
        )
        return _advance_after_side(store, record, side_name, completed)
    ensure_temporary_worktree(side)
    outcome = start_side_merge(
        side,
        paired_code=_paired_code(record),
        crossing_owner=("leaf" if record.contractKind == "leaf" else "master", record.taskId),
    )
    if outcome.state == "resolution-required":
        updated_side = side.model_copy(
            update={
                "state": "resolution-required",
                "conflictFiles": outcome.conflicts,
                "crossingReport": outcome.crossing_report,
            }
        )
        return update_record(store, record, phase=resolution_phase(side_name), side=updated_side)
    updated_side = side.model_copy(
        update={
            "state": "completed",
            "resultHead": side_branch_head(side),
            "crossingReport": outcome.crossing_report,
        }
    )
    record, updated_side, conflicted = restore_parked_wip(store, record, side_name, updated_side)
    if conflicted:
        return record
    return _advance_after_side(store, record, side_name, updated_side)


def _knowledge_validation_refused(
    error: SyncKnowledgeValidationError, record: SyncOperationRecord, fetch: dict[str, object]
) -> WorktreeCommandResult:
    """The validator refused the staged memory merge (MIK-R22): name every violation and the way on.

    The merge stays staged and the phase is unchanged, so the same call that reached the refusal
    resumes it: ``continue`` for a retained conflict, a plain rerun for the automatic merge.
    """

    worktree = record.memory.worktree if record.memory is not None else "the memory worktree"
    retained = record.phase == "memory-resolution-required"
    rerun = "worktree_sync with resolution_action='continue'" if retained else "worktree_sync"
    summary = (
        f"{error}\nRecovery: repair these files in {worktree}, stage them (git add), then rerun "
        f"{rerun}; or cancel the sync with resolution_action='cancel'."
    )
    return manual_repair_result("sync-knowledge-validation-refused", summary, record, fetch)


def _paired_code(record: SyncOperationRecord) -> PairedCode | None:
    """The code commit a memory merge is validated against: the code side's settled result."""

    code = record.code
    if code.state != "completed" or not code.resultHead:
        return None
    return PairedCode(repository=Path(code.repository), commit=code.resultHead)


def _continue_resolution(
    contract: WorktreeContract,
    store: SyncOperationStore,
    record: SyncOperationRecord,
    fetch: dict[str, object],
) -> WorktreeCommandResult:
    if record.phase not in {"code-resolution-required", "memory-resolution-required"}:
        return manual_repair_result(
            "sync-resolution-not-required",
            "The active transaction has no retained conflict to continue.",
            record,
            fetch,
        )
    side = _retained_side(record)
    if side.wipState == "restore-conflict":
        return _continue_parked_wip_restore(contract, store, record, fetch)
    return _finish_retained_merge(contract, store, record, fetch)


def _retained_side(record: SyncOperationRecord) -> SyncSideRecord:
    """The side whose conflict the retained phase names; the phase is the whole address."""

    side = record.code if record.phase == "code-resolution-required" else record.memory
    assert side is not None
    return side


def _finish_retained_merge(
    contract: WorktreeContract,
    store: SyncOperationStore,
    record: SyncOperationRecord,
    fetch: dict[str, object],
) -> WorktreeCommandResult:
    """Validate and commit a retained merge whose conflicts are all resolved and staged."""

    side_name: SyncSide = "code" if record.phase == "code-resolution-required" else "memory"
    side = _retained_side(record)

    try:
        result_head = continue_side_merge(side, paired_code=_paired_code(record))
    except SyncKnowledgeValidationError as error:
        return _knowledge_validation_refused(error, record, fetch)
    except SyncGitProofError as error:
        refreshed = side.model_copy(update={"conflictFiles": content_conflicts(side)})
        record = update_record(store, record, phase=record.phase, side=refreshed)
        return manual_repair_result("sync-resolution-incomplete", str(error), record, fetch)
    completed = side.model_copy(
        update={
            "state": "completed",
            "resultHead": result_head,
            "conflictFiles": (),
        }
    )
    record, completed, conflicted = restore_parked_wip(store, record, side_name, completed)
    if conflicted:
        return resolution_required(record, fetch)
    record = _advance_after_side(store, record, side_name, completed)
    return _run_automatic(contract, store, record, fetch)


def _continue_parked_wip_restore(
    contract: WorktreeContract,
    store: SyncOperationStore,
    record: SyncOperationRecord,
    fetch: dict[str, object],
) -> WorktreeCommandResult:
    """Finish a parked-candidate reapply the agent resolved; the source merge already landed."""

    side_name: SyncSide = "code" if record.phase == "code-resolution-required" else "memory"
    side = record.code if side_name == "code" else record.memory
    assert side is not None
    try:
        record = settle_resolved_parked_wip(store, record, side_name, side)
    except SyncGitProofError as error:
        refreshed = side.model_copy(update={"conflictFiles": content_conflicts(side)})
        record = update_record(store, record, phase=record.phase, side=refreshed)
        return manual_repair_result("sync-resolution-incomplete", str(error), record, fetch)
    completed = side.model_copy(
        update={"state": "completed", "wipState": "restored", "conflictFiles": ()}
    )
    record = _advance_after_side(store, record, side_name, completed)
    return _run_automatic(contract, store, record, fetch)


def _reconcile_completed_sides(
    store: SyncOperationStore, record: SyncOperationRecord
) -> SyncOperationRecord:
    """Adopt a side whose merge is already committed, returning any candidate it parks."""

    if record.phase == "running-code" and _side_live_complete(record.code):
        side = record.code.model_copy(
            update={"state": "completed", "resultHead": side_branch_head(record.code)}
        )
        record, side, conflicted = restore_parked_wip(store, record, "code", side)
        if not conflicted:
            record = _advance_after_side(store, record, "code", side)
    if (
        record.phase == "running-memory"
        and record.memory is not None
        and (
            record.memory.plan in {"already-current", "skip"} or _side_live_complete(record.memory)
        )
    ):
        side = record.memory.model_copy(
            update={
                "state": "completed",
                "resultHead": (
                    record.memory.preSyncHead
                    if record.memory.plan == "skip"
                    else side_branch_head(record.memory)
                ),
            }
        )
        record, side, conflicted = restore_parked_wip(store, record, "memory", side)
        if not conflicted:
            record = _advance_after_side(store, record, "memory", side)
    return record


def _side_live_complete(side: SyncSideRecord) -> bool:
    if side.plan == "already-current":
        return True
    if side.plan == "skip":
        return True
    ensure_temporary_worktree(side)
    return side_merge_completed(side)


def _advance_after_side(
    store: SyncOperationStore,
    record: SyncOperationRecord,
    side_name: SyncSide,
    side: SyncSideRecord | None,
) -> SyncOperationRecord:
    phase = "running-memory" if side_name == "code" and record.memory is not None else "finalizing"
    return update_record(store, record, phase=phase, side=side, side_name=side_name)

"""Exact Git mutations and proofs for resumable code and memory-content sync.

The memory side excludes its root memory.md cache from candidate, conflict, and merge-tree
identity. Code-side files keep ordinary Git semantics, including a file named memory.md.
"""

from __future__ import annotations

import subprocess
from dataclasses import dataclass, replace
from pathlib import Path
from typing import Literal

from agents_remember.kernel.git_command import run_git
from agents_remember.kernel.memory_cache import prepare_memory_cache, refresh_memory_cache
from agents_remember.worktrees.knowledge_crossing import (
    CrossingSyncError,
    apply_crossing,
    close_crossing_history,
    crossing_plan,
    merge_base,
    merge_structure,
    write_crossing_report,
)
from agents_remember.worktrees.knowledge_validation import PairedCode, memory_commit_refusal
from agents_remember.worktrees.modules.git import (
    branch_commit,
    current_branch,
    head_commit,
    is_ancestor,
    repository_identity,
)
from agents_remember.worktrees.services import CrossingPlanView
from agents_remember.worktrees.sync_transaction_state import SyncSideRecord


class SyncGitProofError(RuntimeError):
    """Live Git state cannot be attributed exactly to the journaled sync."""


class SyncKnowledgeValidationError(SyncGitProofError):
    """The knowledge validator (MIK-R22) refuses the staged memory merge; it stays staged."""


@dataclass(frozen=True)
class SideMergeOutcome:
    """What one side's merge attempt reached.

    ``state`` is ``completed`` or ``resolution-required``; ``conflicts`` names the paths still
    unmerged; ``message`` is Git's own text for a conflict. ``crossing_report`` is the path of the
    structural knowledge merge's report, when it left items for the curator or converted a side.
    """

    state: str
    conflicts: tuple[str, ...] = ()
    message: str = ""
    crossing_report: str = ""


def read_ref(repository: Path, ref: str) -> str | None:
    valid = run_git(repository, ["check-ref-format", ref])
    if valid.returncode != 0:
        raise SyncGitProofError(valid.stderr.strip() or f"invalid sync authority ref {ref!r}")
    result = run_git(
        repository,
        ["rev-parse", "--verify", "--quiet", "--end-of-options", f"{ref}^{{commit}}"],
    )
    if result.returncode == 0:
        return result.stdout.strip()
    if result.returncode == 1:
        return None
    raise SyncGitProofError(result.stderr.strip() or f"could not inspect sync authority ref {ref}")


def create_pinned_ref(repository: Path, ref: str, commit: str) -> None:
    current = read_ref(repository, ref)
    if current is not None:
        if current != commit:
            raise SyncGitProofError(f"sync authority ref {ref} pins another commit")
        return
    zeros = "0" * len(commit)
    result = run_git(repository, ["update-ref", ref, commit, zeros])
    if result.returncode != 0:
        raise SyncGitProofError(result.stderr.strip() or f"could not create {ref}")


def delete_pinned_ref(repository: Path, ref: str, expected: str) -> None:
    current = read_ref(repository, ref)
    if current is None:
        return
    if current != expected:
        raise SyncGitProofError(f"sync authority ref {ref} changed before cleanup")
    result = run_git(repository, ["update-ref", "-d", ref, expected])
    if result.returncode != 0:
        raise SyncGitProofError(result.stderr.strip() or f"could not delete {ref}")


def ensure_temporary_worktree(side: SyncSideRecord) -> None:
    if not side.temporary:
        require_side_checkout(side)
        return
    repository = Path(side.repository)
    worktree = Path(side.worktree)
    if worktree.exists():
        require_side_checkout(side)
        return
    worktree.parent.mkdir(parents=True, exist_ok=True)
    result = run_git(repository, ["worktree", "add", str(worktree), side.workBranch])
    if result.returncode != 0:
        raise SyncGitProofError(
            result.stderr.strip() or f"could not create temporary {side.side} sync worktree"
        )
    require_side_checkout(side)


def require_side_checkout(side: SyncSideRecord) -> None:
    repository = Path(side.repository)
    worktree = Path(side.worktree)
    if repository_identity(worktree) != repository_identity(repository):
        raise SyncGitProofError(f"{side.side} sync worktree changed repository identity")
    if current_branch(worktree) != side.workBranch:
        raise SyncGitProofError(f"{side.side} sync worktree changed its journaled branch")


def remove_temporary_worktree(side: SyncSideRecord) -> None:
    if not side.temporary:
        return
    repository = Path(side.repository)
    worktree = Path(side.worktree)
    if not worktree.exists():
        return
    require_side_checkout(side)
    if git_status(side):
        raise SyncGitProofError(f"temporary {side.side} sync worktree is not clean")
    discard_memory_cache_changes(side)
    result = run_git(repository, ["worktree", "remove", str(worktree)])
    if result.returncode != 0:
        raise SyncGitProofError(
            result.stderr.strip() or f"could not remove temporary {side.side} sync worktree"
        )


def git_status(side: SyncSideRecord) -> str:
    result = run_git(Path(side.worktree), ["status", "--porcelain", *_content_pathspec(side)])
    if result.returncode != 0:
        raise SyncGitProofError(result.stderr.strip() or "could not read sync worktree status")
    return result.stdout.strip()


def worktree_dirty_paths(side: SyncSideRecord) -> tuple[str, ...]:
    """Every dirty path the worktree holds, untracked included.

    NUL separation is the only porcelain form that never quotes a path, so the reported
    paths are exactly the paths git reported.
    """

    result = run_git(
        Path(side.worktree), ["status", "--porcelain", "-z", "-uall", *_content_pathspec(side)]
    )
    if result.returncode != 0:
        raise SyncGitProofError(result.stderr.strip() or "could not read sync worktree status")
    entries = result.stdout.split("\0")
    paths: list[str] = []
    index = 0
    while index < len(entries):
        entry = entries[index]
        index += 1
        if not entry:
            continue
        status = entry[:2]
        paths.append(entry[3:])
        if "R" in status or "C" in status:
            index += 1
    return tuple(paths)


def park_worktree_wip(side: SyncSideRecord, *, message: str) -> str:
    """Stash the exact worktree candidate with its untracked files; return its identity."""

    worktree = Path(side.worktree)
    require_side_checkout(side)
    discard_memory_cache_changes(side)
    result = run_git(
        worktree,
        ["stash", "push", "--include-untracked", "--message", message, *_content_pathspec(side)],
    )
    if result.returncode != 0:
        raise SyncGitProofError(
            result.stderr.strip() or result.stdout.strip() or "git stash push failed"
        )
    if git_status(side):
        raise SyncGitProofError("git stash push left the sync worktree dirty")
    parked = run_git(worktree, ["rev-parse", "--verify", "refs/stash^{commit}"])
    if parked.returncode != 0:
        raise SyncGitProofError("git stash push created no stash entry")
    return parked.stdout.strip()


def apply_parked_wip(side: SyncSideRecord) -> tuple[str, tuple[str, ...]]:
    """Reapply the parked content and retain every genuine content conflict."""

    worktree = Path(side.worktree)
    require_side_checkout(side)
    clean_before = not git_status(side)
    discard_memory_cache_changes(side)
    result = run_git(worktree, ["stash", "apply", "--quiet", side.wipStash])
    raw_conflicts = unmerged_paths(worktree)
    cache_conflict = side.side == "memory" and raw_conflicts == ("memory.md",)
    if side.side == "memory" and "memory.md" in raw_conflicts:
        _remove_memory_cache_from_index(side)
    conflicts = content_conflicts(side)
    if result.returncode == 0 and not conflicts:
        _refresh_memory_cache(side)
        return "applied", ()
    if conflicts:
        return "conflict", conflicts
    if (
        result.returncode == 1
        and cache_conflict
        and clean_before
        and prove_parked_wip_restored(side, head_commit(worktree))
    ):
        discard_memory_cache_changes(side)
        _refresh_memory_cache(side)
        return "applied", ()
    raise SyncGitProofError(
        result.stderr.strip() or result.stdout.strip() or "the parked worktree WIP did not reapply"
    )


def prove_parked_wip_restored(side: SyncSideRecord, carried_head: str) -> bool:
    """Prove the parked candidate is back in the worktree, not silently lost.

    A parked path is restored when the worktree reports it dirty again, or when the
    carried result already holds exactly the parked content (a clean reapply that the
    moved source made identical). Anything else fails the proof.
    """

    dirty = set(worktree_dirty_paths(side))
    for path in side.wipPaths:
        if side.side == "memory" and path == "memory.md":
            continue
        if path in dirty:
            continue
        parked = _revision_blob(side, (f"{side.wipStash}^3:{path}", f"{side.wipStash}:{path}"))
        if parked is not None and parked == _revision_blob(side, (f"{carried_head}:{path}",)):
            continue
        return False
    return True


def discard_conflicted_wip_reapply(side: SyncSideRecord) -> None:
    """Drop a conflicted parked-candidate reapply; the candidate itself stays in its stash."""

    worktree = Path(side.worktree)
    require_side_checkout(side)
    if merge_head(worktree) is not None:
        raise SyncGitProofError(f"{side.side} sync has an active merge outside cancel authority")
    reset = run_git(worktree, ["reset", "--hard"])
    if reset.returncode != 0:
        raise SyncGitProofError(
            reset.stderr.strip() or f"could not clear the {side.side} candidate reapply"
        )


def drop_parked_wip(side: SyncSideRecord) -> bool:
    """Drop exactly the recorded stash entry, and never another one."""

    repository = Path(side.repository)
    listed = run_git(repository, ["stash", "list", "--format=%gd %H"])
    if listed.returncode != 0:
        raise SyncGitProofError(listed.stderr.strip() or "could not list the stash stack")
    for line in listed.stdout.splitlines():
        cells = line.split()
        if len(cells) == 2 and cells[1] == side.wipStash:
            dropped = run_git(repository, ["stash", "drop", cells[0]])
            if dropped.returncode != 0:
                raise SyncGitProofError(
                    dropped.stderr.strip() or "could not drop the parked worktree WIP"
                )
            return True
    return False


def _revision_blob(side: SyncSideRecord, specs: tuple[str, ...]) -> str | None:
    repository = Path(side.repository)
    for spec in specs:
        resolved = run_git(repository, ["rev-parse", "--verify", "--quiet", spec])
        if resolved.returncode == 0:
            return resolved.stdout.strip()
    return None


def merge_head(worktree: Path) -> str | None:
    result = run_git(worktree, ["rev-parse", "--verify", "MERGE_HEAD"])
    return result.stdout.strip() if result.returncode == 0 else None


def unmerged_paths(worktree: Path) -> tuple[str, ...]:
    result = run_git(worktree, ["diff", "--name-only", "--diff-filter=U"])
    if result.returncode != 0:
        raise SyncGitProofError(result.stderr.strip() or "could not inspect merge conflicts")
    return tuple(path for path in result.stdout.splitlines() if path)


def side_merge_completed(side: SyncSideRecord) -> bool:
    worktree = Path(side.worktree)
    if merge_head(worktree) is not None:
        return False
    current = head_commit(worktree)
    return exact_created_head(side, current)


def _content_pathspec(side: SyncSideRecord) -> list[str]:
    return ["--", ".", ":(top,exclude)memory.md"] if side.side == "memory" else []


def content_conflicts(side: SyncSideRecord) -> tuple[str, ...]:
    """Read unresolved content without assigning authority to a memory-side cache."""

    return tuple(
        path
        for path in unmerged_paths(Path(side.worktree))
        if side.side != "memory" or path != "memory.md"
    )


def discard_memory_cache_changes(side: SyncSideRecord) -> None:
    """Restore only the derived path to Git's pre-operation state; discard no content."""

    if side.side != "memory":
        return
    worktree = Path(side.worktree)
    tracked = _require_sync_git(worktree, ["ls-tree", "--name-only", "HEAD", "--", "memory.md"])
    _require_sync_git(worktree, ["clean", "-fdx", "--", "memory.md"])
    if tracked:
        _require_sync_git(
            worktree, ["restore", "--source=HEAD", "--staged", "--worktree", "--", "memory.md"]
        )
    else:
        _remove_memory_cache_from_index(side)


def _remove_memory_cache_from_index(side: SyncSideRecord) -> None:
    _require_sync_git(
        Path(side.worktree), ["rm", "--cached", "--force", "--ignore-unmatch", "--", "memory.md"]
    )


def _require_sync_git(worktree: Path, args: list[str]) -> str:
    result = run_git(worktree, args)
    if result.returncode != 0:
        raise SyncGitProofError(
            result.stderr.strip() or result.stdout.strip() or "sync Git operation failed"
        )
    return result.stdout.strip()


def _refresh_memory_cache(side: SyncSideRecord) -> None:
    if side.side != "memory":
        return
    worktree = Path(side.worktree)
    if not _require_sync_git(worktree, ["ls-tree", "--name-only", "HEAD", "--", "memory.md"]):
        refresh_memory_cache(worktree)


def _require_active_merge(side: SyncSideRecord) -> None:
    worktree = Path(side.worktree)
    if head_commit(worktree) != side.preSyncHead or merge_head(worktree) != side.sourceCommit:
        raise SyncGitProofError(f"{side.side} active merge is not the pinned sync merge")


def _continue_memory_merge(
    side: SyncSideRecord, paired_code: PairedCode | None
) -> SideMergeOutcome:
    """Settle the memory merge: commit it when nothing is unmerged, else hand it to the agent.

    Knowledge is text. A merge with a converted side has already had its ``knowledge/`` and
    ``onboarding/`` paths merged structurally (:func:`_apply_knowledge_merge`), so whatever is still
    unmerged here is an item both sides authored differently, or a file outside those roots, and is
    the agent's to resolve and ``continue``. The staged tree is validated (MIK-R22) before it is
    committed.
    """

    _require_active_merge(side)
    _remove_memory_cache_from_index(side)
    conflicts = content_conflicts(side)
    if conflicts:
        return SideMergeOutcome(state="resolution-required", conflicts=conflicts)
    validate_staged_resolution(side)
    return SideMergeOutcome(
        state="completed", conflicts=(), message=_finish_staged_memory_merge(side, paired_code)
    )


def _existing_side_merge(
    side: SyncSideRecord, paired_code: PairedCode | None
) -> SideMergeOutcome | None:
    """Resume only the admitted merge or its exact completed output."""
    worktree = Path(side.worktree)
    if merge_head(worktree) is not None:
        _require_active_merge(side)
        if side.side == "memory" and side.plan == "merge":
            return _continue_memory_merge(side, paired_code)
        return SideMergeOutcome(state="resolution-required", conflicts=unmerged_paths(worktree))
    if side_merge_completed(side):
        return SideMergeOutcome(state="completed", message=head_commit(worktree))
    return None


def start_side_merge(
    side: SyncSideRecord,
    *,
    paired_code: PairedCode | None = None,
    crossing_owner: tuple[Literal["leaf", "master"], str] | None = None,
) -> SideMergeOutcome:
    """Attempt the pinned merge; only genuine content conflicts require resolution.

    ``paired_code`` is the code commit the memory merge is paired with (the code side's result):
    the knowledge validator checks the merged memory tree against it (MIK-R22 rule 8).
    ``crossing_owner`` names who performs the sync (the leaf, or the master line's task): a memory
    merge with a converted side has its knowledge paths merged structurally (MIK-R24 rule 8 step 3,
    in every managed sync by MIK-R26 rule 2), and a conflicted record's row is that owner's.
    """

    worktree = Path(side.worktree)
    require_side_checkout(side)
    existing = _existing_side_merge(side, paired_code)
    if existing is not None:
        return existing
    if head_commit(worktree) != side.preSyncHead:
        raise SyncGitProofError(f"{side.side} work branch moved after sync admission")
    if git_status(side):
        raise SyncGitProofError(f"{side.side} sync requires a clean worktree before merging")
    discard_memory_cache_changes(side)
    memory_merge = side.side == "memory" and side.plan == "merge"
    knowledge = _knowledge_merge(side, paired_code, crossing_owner, memory_merge=memory_merge)
    # A memory merge stops before committing so the structural merge and the validator see it staged.
    no_commit = ["--no-commit"] if memory_merge else []
    result = run_git(worktree, ["merge", *no_commit, "--no-edit", side.sourceCommit])
    if knowledge is not None:
        return _apply_knowledge_merge(side, knowledge, result, paired_code)
    if result.returncode == 0:
        if memory_merge:
            return _continue_memory_merge(side, paired_code)
        result_head = head_commit(worktree)
        if not exact_created_head(side, result_head):
            raise SyncGitProofError(f"{side.side} merge did not create the exact admitted head")
        _refresh_memory_cache(side)
        return SideMergeOutcome(state="completed", message=result_head)
    conflicts = unmerged_paths(worktree)
    if result.returncode == 1 and merge_head(worktree) == side.sourceCommit and conflicts:
        if memory_merge:
            return _continue_memory_merge(side, paired_code)
        return SideMergeOutcome(
            state="resolution-required",
            conflicts=conflicts,
            message=(result.stderr or result.stdout).strip(),
        )
    raise SyncGitProofError(
        (result.stderr or result.stdout).strip() or f"{side.side} source merge failed"
    )


def _apply_knowledge_merge(
    side: SyncSideRecord,
    plan: CrossingPlanView,
    result: subprocess.CompletedProcess[str],
    paired_code: PairedCode | None,
) -> SideMergeOutcome:
    """Replace the started merge's knowledge and onboarding paths with the structural plan.

    The report is written when the merge leaves something to read: an item for the curator, or a
    side it converted (a crossing). A clean merge of converted lines writes none.
    """

    worktree = Path(side.worktree)
    if result.returncode not in {0, 1} or merge_head(worktree) != side.sourceCommit:
        raise SyncGitProofError(
            (result.stderr or result.stdout).strip() or "memory knowledge merge failed"
        )
    report = ""
    try:
        apply_crossing(worktree, plan)
        if plan.conflict_versions or plan.report.get("converted"):
            report = write_crossing_report(
                worktree, side.preSyncHead, side.sourceCommit, plan
            ).as_posix()
    except CrossingSyncError as error:
        raise SyncGitProofError(str(error)) from error
    outcome = _continue_memory_merge(side, paired_code)
    return replace(outcome, crossing_report=report)


def _knowledge_merge(
    side: SyncSideRecord,
    paired_code: PairedCode | None,
    owner: tuple[Literal["leaf", "master"], str] | None,
    *,
    memory_merge: bool,
) -> CrossingPlanView | None:
    """The structural plan of a memory merge with a converted side, or ``None`` for a plain merge.

    MIK-R24 rule 8 step 3 in every managed sync (MIK-R26 rule 2): three converted trees merge as
    they are, and a crossing converts its unconverted trees first. Only three unconverted trees are
    left to Git. It runs before Git touches the worktree, so a failing step leaves the line
    unchanged.
    """

    if not memory_merge:
        return None
    worktree = Path(side.worktree)
    try:
        base = merge_base(worktree, side.preSyncHead, side.sourceCommit)
        if merge_structure(worktree, base, side.preSyncHead, side.sourceCommit) == "plain":
            return None
        if owner is None:
            raise CrossingSyncError(
                "crossing sync step 'markers' failed: the sync names no leaf or master owner"
            )
        return crossing_plan(
            worktree,
            (base, side.preSyncHead, side.sourceCommit),
            paired_code=paired_code,
            owner=owner,
        )
    except CrossingSyncError as error:
        raise SyncGitProofError(str(error)) from error


def _finish_staged_memory_merge(side: SyncSideRecord, paired_code: PairedCode | None) -> str:
    """Publish one ordinary memory merge with exact parents and no cache in its tree.

    The staged tree is validated first against both parents (MIK-R22 rule 8); a refused merge is
    left staged for the agent to repair and continue.
    """

    worktree = Path(side.worktree)
    _require_active_merge(side)
    prepare_memory_cache(worktree)
    _require_sync_git(worktree, ["add", "--", ".gitignore"])
    try:
        close_crossing_history(worktree, (side.preSyncHead, side.sourceCommit))
    except CrossingSyncError as error:
        raise SyncGitProofError(str(error)) from error
    refusal = memory_commit_refusal(
        memory_repository=worktree,
        candidate_tree=_require_sync_git(worktree, ["write-tree"]),
        bases=(side.preSyncHead, side.sourceCommit),
        paired_code=paired_code,
    )
    if refusal is not None:
        raise SyncKnowledgeValidationError(refusal)
    _require_sync_git(worktree, ["commit", "--no-edit"])
    result_head = head_commit(worktree)
    if not exact_created_head(side, result_head):
        raise SyncGitProofError("memory merge commit does not have the pinned parents")
    _refresh_memory_cache(side)
    return result_head


def continue_side_merge(side: SyncSideRecord, *, paired_code: PairedCode | None = None) -> str:
    """Validate a staged agent resolution and commit the exact retained merge."""

    worktree = Path(side.worktree)
    require_side_checkout(side)
    if merge_head(worktree) is None:
        if not exact_created_head(side, head_commit(worktree)):
            raise SyncGitProofError(
                f"{side.side} merge state disappeared without an operation-owned commit"
            )
        _refresh_memory_cache(side)
        return head_commit(worktree)
    _require_active_merge(side)
    validate_staged_resolution(side)
    if side.side == "memory":
        _remove_memory_cache_from_index(side)
        return _finish_staged_memory_merge(side, paired_code)
    _require_sync_git(worktree, ["commit", "--no-edit"])
    result_head = head_commit(worktree)
    if not exact_created_head(side, result_head):
        raise SyncGitProofError(f"{side.side} merge commit does not have the pinned parents")
    return result_head


def validate_staged_resolution(side: SyncSideRecord) -> None:
    """Read-only proof of the exact retained content merge, excluding the memory cache."""

    worktree = Path(side.worktree)
    require_side_checkout(side)
    _require_active_merge(side)
    conflicts = content_conflicts(side)
    if conflicts:
        raise SyncGitProofError(
            f"{side.side} resolution still has unmerged paths: {', '.join(conflicts[:30])}"
        )
    unstaged = run_git(worktree, ["diff", "--quiet", *_content_pathspec(side)])
    if unstaged.returncode != 0:
        raise SyncGitProofError(f"{side.side} resolution has unstaged changes")
    checked = run_git(worktree, ["diff", "--cached", "--check", *_content_pathspec(side)])
    if checked.returncode != 0:
        raise SyncGitProofError(
            checked.stdout.strip() or checked.stderr.strip() or "staged resolution is invalid"
        )


def _abort_failure(
    side: SyncSideRecord, aborted: subprocess.CompletedProcess[str]
) -> SyncGitProofError:
    """The refusal of a merge abort that did not restore the head, naming Git's own reason."""

    detail = (aborted.stderr or aborted.stdout).strip()
    suffix = f": {detail}" if detail else ""
    return SyncGitProofError(f"{side.side} exact merge abort did not restore its head{suffix}")


def rollback_side(side: SyncSideRecord) -> None:
    """Restore one side only when live history proves the exact sync-owned delta."""

    ensure_temporary_worktree(side)
    worktree = Path(side.worktree)
    current = head_commit(worktree)
    current_merge = merge_head(worktree)
    if current_merge is not None:
        if current != side.preSyncHead or current_merge != side.sourceCommit:
            raise SyncGitProofError(f"{side.side} active merge is outside sync authority")
        # The memory merge removed a tracked cache from the index (_continue_memory_merge); put the
        # derived path back to HEAD first, or `git merge --abort` meets it as an untracked file and
        # refuses (L37: cancel after a memory conflict on a line that still tracks memory.md).
        discard_memory_cache_changes(side)
        aborted = run_git(worktree, ["merge", "--abort"])
        if aborted.returncode != 0 or head_commit(worktree) != side.preSyncHead:
            raise _abort_failure(side, aborted)
    elif current != side.preSyncHead:
        if not exact_created_head(side, current):
            raise SyncGitProofError(
                f"{side.side} has later or unrelated commits; automatic rollback is unsafe"
            )
        if git_status(side):
            raise SyncGitProofError(f"{side.side} has post-sync work; automatic rollback is unsafe")
        discard_memory_cache_changes(side)
        reset = run_git(worktree, ["reset", "--hard", side.preSyncHead])
        if reset.returncode != 0:
            raise SyncGitProofError(reset.stderr.strip() or f"could not restore {side.side} head")
    if head_commit(worktree) != side.preSyncHead:
        raise SyncGitProofError(f"{side.side} rollback did not reach its pinned pre-sync head")
    if git_status(side):
        raise SyncGitProofError(
            f"{side.side} branch is restored but post-sync work remains for manual repair"
        )


def exact_created_head(side: SyncSideRecord, current: str) -> bool:
    """Prove the only two heads the admitted merge can create."""
    if current == side.sourceCommit and is_ancestor(
        Path(side.repository), side.preSyncHead, side.sourceCommit
    ):
        return True
    parents = run_git(Path(side.repository), ["rev-list", "--parents", "-n", "1", current])
    cells = parents.stdout.split()
    return parents.returncode == 0 and cells[1:] == [side.preSyncHead, side.sourceCommit]


def side_branch_head(side: SyncSideRecord) -> str:
    return branch_commit(Path(side.repository), side.workBranch)

"""The gate at direct landing (MIK-R09 rule 3): the branch-addressed leaf closeout.

A direct landing publishes a leaf implemented on the series branch itself, without its own worktree
enclosure, so its sides are read from the series lines:

* **K_B** is the series memory line's head, the commit this landing's memory commit will follow;
* **B** is the code commit K_B's ``Code-Commit`` trailer names -- the code the line last published
  -- which must be an ancestor of the landed code commit;
* **C** is the verified code commit's tree, and **K_C** the memory checkout's exact candidate tree.

**The leaf.** The route names no leaf, so the leaf is the owner of the one open leaf history file in
K_C (``knowledge/history/<leaf-id>.json`` with ``closed: false``). None, or more than one, refuses:
a direct-mode leaf of a converted repository records its rows -- or an empty ``rows`` -- in its own
file, which this landing then closes. This is a choice the packet leaves open (see the L09 report).

A replay of an already published landing (the checkout is clean at a head whose trailer names this
code commit) commits nothing, so it is not gated again.
"""

from __future__ import annotations

import subprocess
from dataclasses import dataclass
from pathlib import Path
from typing import Any

from agents_remember.application.knowledge_gate.gate import GateTrees, judge
from agents_remember.application.knowledge_worklist.base_cache import (
    default_base_cache_directory,
)
from agents_remember.application.knowledge_worklist.compute import (
    Incomplete,
    git_failure,
    incomplete_worklist,
)
from agents_remember.application.knowledge_worklist.leaf import ExplicitSides, worklist_over
from agents_remember.application.knowledge_worklist.planned_effects import declarations_from
from agents_remember.kernel.git_command import (
    GIT_METADATA_TIMEOUT_SECONDS,
    GitRunnerOptions,
    run_git,
)
from agents_remember.memory.conversion.base import own_paired_code_commit
from agents_remember.memory_quality.knowledge_validator.trees import knowledge_tree_from_git
from agents_remember.models.knowledge_files.canonical import (
    CanonicalFormatError,
    canonical_text,
    parse_json,
)
from agents_remember.models.knowledge_files.history import HISTORY_SCHEMA
from agents_remember.tasks.leaf_decisions import LeafDocumentUnresolved, strict_leaf_doc
from agents_remember.worktrees.services import DirectGateSource, DirectGateVerdict
from agents_remember.worktrees.worktree_contract import WorktreeContract

__all__ = ["direct_source", "direct_verdict"]

_HISTORY_PREFIX = "knowledge/history/"


def _git(repository: Path, *args: str) -> str | None:
    result = run_git(repository, list(args), GitRunnerOptions(timeout=GIT_METADATA_TIMEOUT_SECONDS))
    value = result.stdout.strip()
    return value if result.returncode == 0 and value else None


def _open_histories(memory_repository: Path, memory_tree: str) -> list[tuple[str, str, bytes]]:
    tree = knowledge_tree_from_git(memory_repository, memory_tree)
    histories = []
    for path, data in sorted(tree.files.items()):
        if not (path.startswith(_HISTORY_PREFIX) and path.endswith(".json")):
            continue
        try:
            document: Any = parse_json(data.decode("utf-8"))
        except (UnicodeDecodeError, CanonicalFormatError):
            continue  # the validator names a file that does not parse
        if (
            isinstance(document, dict)
            and document.get("schema") == HISTORY_SCHEMA
            and document.get("closed") is False
            and isinstance(document.get("leaf"), str)
        ):
            histories.append((document["leaf"], path, data))
    return histories


def direct_source(
    contract: WorktreeContract, *, code_commit: str, memory_tree: str
) -> DirectGateVerdict:
    """Bind the unique open history source before the route closes it; run no worklist gate."""
    memory = contract.memory_repo_path
    if memory is None:
        return DirectGateVerdict(True, None, "direct landing has no memory repository to gate")
    try:
        return _source(memory, code_commit, memory_tree)
    except subprocess.SubprocessError as error:
        detail = git_failure(error).detail
        return DirectGateVerdict(True, None, f"the mandatory invariant gate (MIK-R09): {detail}")


def direct_verdict(
    contract: WorktreeContract,
    *,
    code_commit: str,
    memory_tree: str,
    source: DirectGateSource | None = None,
) -> DirectGateVerdict:
    """The gate's verdict over a direct landing's exact candidate (the caller probed the marker)."""

    memory = contract.memory_repo_path
    if memory is None:
        return DirectGateVerdict(True, None, "direct landing has no memory repository to gate")
    try:
        selected = _source(
            memory, code_commit, memory_tree if source is None else source.memory_tree
        )
        if selected.refusal is not None:
            return selected
        if source is not None:
            refusal = _closed_source_refusal(memory, memory_tree, selected.source, source)
            if refusal is not None:
                return DirectGateVerdict(True, None, refusal)
        elif not selected.applies:
            return selected
        assert selected.source is not None
        return _verdict(contract, memory, code_commit, memory_tree, selected.source)
    except subprocess.SubprocessError as error:
        detail = git_failure(error).detail
        return DirectGateVerdict(True, None, f"the mandatory invariant gate (MIK-R09): {detail}")


def _source(memory: Path, code_commit: str, memory_tree: str) -> DirectGateVerdict:
    head = _git(memory, "rev-parse", "--verify", "--quiet", "HEAD^{commit}")
    if head is None:
        return DirectGateVerdict(True, None, "the series memory line has no head to land on")
    published = own_paired_code_commit(memory, head)
    if published == code_commit and _git(memory, "rev-parse", f"{head}^{{tree}}") == memory_tree:
        return DirectGateVerdict(False, None, None)  # a replay commits nothing
    histories = _open_histories(memory, memory_tree)
    if len(histories) != 1:
        owners = [owner for owner, _path, _data in histories]
        return DirectGateVerdict(
            True,
            None,
            "the mandatory invariant gate (MIK-R09) refuses this direct landing: it names no leaf, "
            f"and the memory candidate holds {len(owners)} open leaf history file(s) "
            f"({', '.join(owners) or 'none'}); exactly one, knowledge/history/<leaf-id>.json with "
            "closed: false, names the leaf whose rows this landing publishes and closes",
        )
    owner, path, data = histories[0]
    return DirectGateVerdict(
        True,
        owner,
        None,
        DirectGateSource(memory.resolve(), head, memory_tree, code_commit, owner, path, data),
    )


def _closed_source_refusal(
    memory: Path,
    memory_tree: str,
    selected: DirectGateSource | None,
    source: DirectGateSource,
) -> str | None:
    """Require the same source namespace and rows, with only its closing flag changed."""
    if selected != source:
        return "the direct landing's selected history source or memory head changed; retry the gate"
    original = parse_json(source.history_bytes.decode("utf-8"))
    assert isinstance(original, dict)
    closed = canonical_text({**original, "closed": True}).encode("utf-8")
    files = knowledge_tree_from_git(memory, memory_tree).files
    if files.get(source.history_path) != closed:
        return (
            f"the direct landing's closed candidate changed the selected history source "
            f"{source.history_path}; only its closing flag may change before the gate"
        )
    if _open_histories(memory, memory_tree):
        return (
            "the closed direct-landing candidate contains another open leaf history; retry the gate"
        )
    return None


def _verdict(
    contract: WorktreeContract,
    memory: Path,
    code_commit: str,
    memory_tree: str,
    source: DirectGateSource,
) -> DirectGateVerdict:
    owner, head = source.owner, source.memory_head
    published = own_paired_code_commit(memory, head)
    document = _worklist(contract, _DirectSides(owner, head, published, code_commit, memory_tree))
    trees = GateTrees(
        code_repository=contract.code_repo_path,
        code_tree=code_commit,
        memory_repository=memory,
        memory_tree=memory_tree,
        validation_bases=(head,),
        base_code_commit=published or code_commit,
        cache_directory=default_base_cache_directory(contract.coordination_root),
    )
    result = judge(document, None, trees, owner)
    return DirectGateVerdict(True, owner, result.refusal())


@dataclass(frozen=True)
class _DirectSides:
    owner: str
    head: str
    published: str | None
    code_commit: str
    memory_tree: str


def _worklist(contract: WorktreeContract, direct: _DirectSides) -> dict[str, Any]:
    owner, head, published = direct.owner, direct.head, direct.published
    code_commit, memory_tree = direct.code_commit, direct.memory_tree
    if published is None or not _is_ancestor(contract.code_repo_path, published, code_commit):
        return incomplete_worklist(
            Incomplete(
                "pairing",
                f"the series memory head {head} names no code commit ({published}) that is an "
                f"ancestor of the landed code commit {code_commit}",
            ),
            owner=owner,
            pairing=None,
        )
    try:
        found = strict_leaf_doc(contract.task_root, owner)
        sides = ExplicitSides(
            code_repository=contract.code_repo_path,
            base=published,
            memory_repository=contract.memory_repo_path or contract.code_repo_path,
            memory_base=head,
            memory_candidate=memory_tree,
            code_candidate=code_commit,
            maintenance_scope=bool(found is not None and found[1].knowledgeMaintenanceScope),
            owner=owner,
            cache_directory=default_base_cache_directory(contract.coordination_root),
            expected_effects=None
            if found is None
            else declarations_from(found[1].expectedKnowledgeEffects),
            coordination_root=contract.coordination_root,
        )
        document = worklist_over(contract, sides)
    except LeafDocumentUnresolved as error:
        return incomplete_worklist(
            Incomplete("leaf task document", str(error)), owner=owner, pairing=None
        )
    except subprocess.SubprocessError as error:
        return incomplete_worklist(git_failure(error), owner=owner, pairing=None)
    except Exception as error:  # the run's own failure blocks, named
        return incomplete_worklist(
            Incomplete("worklist run", f"{type(error).__name__}: {error}"),
            owner=owner,
            pairing=None,
        )
    if document is None:  # both sides unconverted: the caller's probe said otherwise
        return incomplete_worklist(
            Incomplete("K_C", "neither memory side holds the layout marker"),
            owner=owner,
            pairing=None,
        )
    return document


def _is_ancestor(repository: Path, ancestor: str, commit: str) -> bool:
    result = run_git(
        repository,
        ["merge-base", "--is-ancestor", ancestor, commit],
        GitRunnerOptions(timeout=GIT_METADATA_TIMEOUT_SECONDS),
    )
    return result.returncode == 0

"""Render exact managed-sync tree measurements on the live review surface (ICR-R22)."""

from __future__ import annotations

from agents_remember.application.review_candidate_resolution import ReviewCandidateResolution
from agents_remember.application.review_final_output_receipt import (
    comparison_key,
    select_review_comparison,
)
from agents_remember.application.review_sync_rebinding import (
    read_review_sync_rebinding,
    rebinding_names_the_generation,
)
from agents_remember.memory.knowledge.refusals import KnowledgeStorageError
from agents_remember.models.knowledge.review_external_movement import ExternalGitMovement
from agents_remember.models.knowledge.review_final_output_receipt import tree_comparison_digest
from agents_remember.models.knowledge.review_staleness import (
    ReviewStaleness,
    ReviewSyncMovement,
    ReviewSyncMovementState,
)
from agents_remember.models.knowledge.review_sync_rebinding import (
    ReviewSyncRebinding,
    ReviewSyncRebindingVerdict,
)
from agents_remember.models.knowledge.review_trees import ReviewTreeComparisonRecord
from agents_remember.worktrees.worktree_contract import WorktreeContract

_SUPERSESSION = "Open and record a successor tree comparison for the resolved pair; retain the reviewed source comparison as previous input."


def review_sync_movement(resolved: ReviewCandidateResolution) -> ReviewSyncMovement | None:
    contract = resolved.contract
    if (
        contract is None
        or contract.kind != "leaf"
        or resolved.closed_leaf is not None
        or (resolved.trees is not None and not resolved.trees.live)
    ):
        return None
    try:
        return _measured(contract)
    except (KnowledgeStorageError, OSError, RuntimeError, ValueError) as error:
        return _unavailable(None, str(error))


def _measured(contract: WorktreeContract) -> ReviewSyncMovement | None:
    selection = select_review_comparison(contract.task_root, contract.leaf_id)
    comparison = selection.comparison
    if comparison is None:
        return None if selection.state == "no-comparison" else _unavailable(None, selection.detail)
    read = read_review_sync_rebinding(
        contract.task_root, contract.leaf_id, comparison_key(comparison)
    )
    if read.state == "not-recorded":
        return None
    record = rebinding_names_the_generation(read, comparison)
    if record is None:
        return _unavailable(comparison, read.detail)
    return _project(record)


def _source_fields(comparison: ReviewTreeComparisonRecord | None) -> dict:
    return {
        "movement_version": "ar-review-sync-movement/v2",
        "comparison": comparison,
        "reviewed_binding_digest": None
        if comparison is None
        else tree_comparison_digest(comparison),
        "reviewed_candidate_code_tree_id": None
        if comparison is None
        else comparison.code_candidate.tree,
        "reviewed_candidate_memory_tree_id": None
        if comparison is None
        else comparison.memory_candidate.tree,
        "successor_action": _SUPERSESSION,
    }


def _unavailable(comparison: ReviewTreeComparisonRecord | None, reason: str) -> ReviewSyncMovement:
    return ReviewSyncMovement(
        binding_state="unavailable",
        reason=reason,
        statement=f"No usable exact code and memory tree measurement is available: {reason}",
        record_readable=False,
        **_source_fields(comparison),
    )


def _project(record: ReviewSyncRebinding) -> ReviewSyncMovement:
    code_moved = record.code_match == "differs-from-reviewed-input"
    memory_moved = record.memory_match == "differs-from-reviewed-input"
    states: dict[ReviewSyncRebindingVerdict, ReviewSyncMovementState] = {
        "current": "current",
        "moved": "stale",
        "unmeasured": "not-measured",
    }
    moved = tuple(
        name
        for name, happened in (
            (f"code-candidate-tree:{record.comparison.code_candidate.tree}", code_moved),
            (f"memory-candidate-tree:{record.comparison.memory_candidate.tree}", memory_moved),
        )
        if happened
    )
    return ReviewSyncMovement(
        binding_state=states[record.state],
        moved_identities=moved,
        reason=record.memory_detail if record.state == "unmeasured" else None,
        statement=record.statement(),
        resolved_code_head=record.resolved_code_head if code_moved else None,
        resolved_candidate_code_tree_id=record.resolved_candidate_code_tree_id
        if code_moved
        else None,
        resolved_candidate_memory_tree_id=record.resolved_candidate_memory_tree_id
        if memory_moved
        else None,
        **_source_fields(record.comparison),
    )


def review_staleness_with_external_movement(
    staleness: ReviewStaleness,
    movement: ExternalGitMovement | None,
    sync_movement: ReviewSyncMovement | None,
) -> ReviewStaleness:
    """Fold a measured raw-Git movement into the staleness a review publishes (ICR-R23@v1).

    **A replaced identity is the strongest fact either measurement can report**, and it outranks both
    the reader's carried comparison identity and a recorded managed-sync rebinding: R17's ``current``
    means "the displayed comparison is the candidate's current comparison", which stops being true the
    moment the branch was rewritten under it, and a rebinding that a *later* raw operation has already
    invalidated describes a pair the leaf no longer holds. The packet's failure clause is exactly this
    state -- an unrecognized transition reusing stale assessment as current -- so the movement both
    sets ``stale`` and publishes the exact identities that were replaced.

    **An absence is folded too, and it is not promoted into a movement.** When the boundary reports
    ``not-measured`` or ``unavailable`` -- a checkout that left its declared branch, a recorded object
    that is gone, a generation that could not be read -- this surface cannot claim the displayed
    comparison is the candidate's current one either, because the comparison was composed from
    whatever the checkout holds and nothing compared it against the leaf's declared identities. It
    becomes ``not-measured``, carrying the boundary's own sentence and reason, and it is deliberately
    *not* ``stale``: no movement was observed, and ``stale`` additionally disables submission, which
    is a consequence the absence has not earned. A recorded *measurement* of movement still wins over
    the absence -- R22's rebinding measured a moved input, and one measured movement outranks one
    unperformed comparison.
    """

    if movement is not None and movement.binding_state == "stale":
        return ReviewStaleness(
            state="stale",
            statement=movement.statement,
            previous_comparison_ref=(
                staleness.previous_comparison_ref or movement.reviewed_binding_digest
            ),
            moved=movement.moved_identities,
        )
    folded = review_staleness_with_sync_movement(staleness, sync_movement)
    if (
        movement is not None
        and movement.binding_state in {"not-measured", "unavailable"}
        and folded.state != "stale"
    ):
        return ReviewStaleness(state="not-measured", statement=movement.statement)
    return folded


def review_staleness_with_sync_movement(
    staleness: ReviewStaleness, movement: ReviewSyncMovement | None
) -> ReviewStaleness:
    """Fold a measured sync movement into the staleness a review publishes.

    **The movement outranks the reader's carried identity**, because it is the stronger fact: a
    recorded sync that moved the reviewed inputs means the review does not describe the pair whatever
    the reader was shown, and R17's ``current`` -- "the displayed comparison is the candidate's current
    comparison" -- would let the moved review keep reading as untouched, which is the packet's own
    non-conforming example. Submission follows automatically: the payload's constructor refuses a
    ``stale`` comparison offered for submission.

    The previous input labelled here is a real one in both cases: the identity the reader carried when
    they carried a mismatching one, and otherwise the comparison identity the reviewed generation
    bound -- never an identity nobody held. A movement that measured agreement changes nothing.
    """

    if movement is None:
        return staleness
    if movement.binding_state in {"not-measured", "unavailable"} and staleness.state != "stale":
        return ReviewStaleness(state="not-measured", statement=movement.statement)
    if movement.binding_state != "stale":
        return staleness
    carried = staleness.previous_comparison_ref
    return ReviewStaleness(
        state="stale",
        statement=movement.statement,
        previous_comparison_ref=carried or movement.reviewed_binding_digest,
        moved=movement.moved_identities,
    )

"""A managed sync's knowledge half: markers, conversion, structural merge, validation (MIK-R24 rule 8).

A managed sync is a *crossing sync* when at least one of its merge base, its own side and the
incoming side is unconverted and at least one is converted. :func:`cross` runs the steps on the three
memory trees and returns a :class:`CrossingPlan` -- the merged ``knowledge/`` and ``onboarding/``
files, the conflicts, and the report -- without touching any repository. The managed sync
transaction applies the plan to its merge (``worktrees/knowledge_crossing``); if any step fails,
:class:`CrossingError` names it and the line is left unchanged.

**Every managed sync of converted memory merges this way (MIK-R26 rule 2).** When all three trees
are converted, steps 1 and 2 have nothing to do -- no marker is moved and nothing is converted --
and step 3 merges the three trees as they are, so two lines that both re-anchored the same entry
never conflict on mechanical anchor fields. Only a merge whose three trees are all unconverted is
left to plain Git, and :func:`cross` refuses to be asked about one.

1. **Markers first.** When the own side is a leaf line, the Update History no-impact markers that
   leaf added (``No content impact:``/``No route impact:``, lines absent from the base) become
   ``onboarding_trace`` rows ``{subject, disposition: no_impact, reason: MARKER_ROW_REASON,
   markers: [<marker line>, ...]}`` in the leaf's history file, before its tree is converted: the
   marker text goes in ``markers``, one entry per moved line, and ``reason`` is a short fixed
   summary (L24 ruling N1).
2. **Convert** every unconverted tree with the converted side's pinned version; fallback cards use
   the own side's paired code commit on every side. (The commit route's converted base,
   ``base.GitBaseConverter``, uses the base's own ``Code-Commit`` instead; the two differ only for
   rule 2 fallback cards -- see there.)
3. **Merge structurally** (:mod:`.crossing`).
4. **Conflicts** are returned for the curator: overlapping authored edits and reference-number
   collisions. A record conflict is resolved through the writer; its row belongs to the leaf's
   history file, or on a master line to ``<task-id>-crossing-<n>``, which the plan names.
5. **Validate.** Enforced where the merge is committed, not here: the managed sync's commit step
   runs the knowledge validator (``memory_commit_refusal``) over the staged merge against both
   parents, and ``GitBaseConverter`` replaces the unconverted parent by its conversion (rule 7). A
   refusal leaves the merge staged for the curator.
"""

from __future__ import annotations

import re
from collections.abc import Mapping
from dataclasses import dataclass, field
from pathlib import Path, PurePosixPath
from typing import Any, Final, Literal

from agents_remember.kernel.onboarding_doc import NO_IMPACT_MARKER_PATTERN, new_history_lines
from agents_remember.memory.conversion.code_objects import CodeObjects
from agents_remember.memory.conversion.convert import (
    OVERVIEW,
    MemoryInput,
    convert_memory,
    route_of,
)
from agents_remember.memory.conversion.crossing import Conflict, merge_trees
from agents_remember.models.knowledge.base import PROSE_MAX_LENGTH
from agents_remember.models.knowledge_files.canonical import canonical_text, parse_json
from agents_remember.models.knowledge_files.documents import (
    LAYOUT_MARKER_PATH,
    ONBOARDING_ROOT,
    RECORD_DIRECTORIES,
    history_path,
)
from agents_remember.models.knowledge_files.ids import mint_id

Step = Literal["markers", "convert", "merge", "validate"]
_CROSSING_FILE: Final = re.compile(
    r"^knowledge/history/(?P<task>.+)-crossing-(?P<n>[1-9][0-9]*)\.json$"
)


class CrossingError(RuntimeError):
    """A crossing step could not complete; the line is left unchanged."""

    def __init__(self, step: Step, message: str) -> None:
        super().__init__(f"crossing sync step '{step}' failed: {message}")
        self.step = step


@dataclass(frozen=True)
class HistoryOwner:
    """Who performs the sync: a leaf (its ID) or a master line (its task ID)."""

    kind: Literal["leaf", "master"]
    id: str


@dataclass
class CrossingPlan:
    """The merged knowledge/onboarding files (``None`` = delete) and what the curator must resolve."""

    files: dict[str, bytes | None]
    conflicts: list[Conflict]
    report: dict[str, Any] = field(default_factory=dict)
    conflict_versions: dict[str, tuple[bytes | None, bytes | None, bytes | None]] = field(
        default_factory=dict
    )


def _version(tree: MemoryInput) -> str | None:
    data = tree.files.get(LAYOUT_MARKER_PATH)
    if data is None:
        return None
    return str(parse_json(data.decode("utf-8"))["conversion"])


def _card_subject(card: str) -> str:
    relative = card.removeprefix(f"{ONBOARDING_ROOT}/")
    if PurePosixPath(relative).name == OVERVIEW:
        route = route_of(card)
        return "onboarding:overview" if route == "." else f"onboarding:{route}/overview"
    return f"onboarding:{relative.removesuffix('.md')}"


def marker_rows(base: MemoryInput, own: MemoryInput) -> list[dict[str, Any]]:
    """The own leaf's no-impact markers, as ``onboarding_trace`` rows (step 1)."""

    rows: list[dict[str, Any]] = []
    for card in sorted(own.files):
        if not (card.startswith(f"{ONBOARDING_ROOT}/") and card.endswith(".md")):
            continue
        before = base.files.get(card)
        added = new_history_lines(
            before.decode("utf-8") if before is not None else None, own.files[card].decode("utf-8")
        )
        markers = [
            piece
            for line in added
            if NO_IMPACT_MARKER_PATTERN.search(line)
            for piece in marker_pieces(line)
        ]
        if markers:
            rows.append(
                {
                    "id": mint_id("history_row"),
                    "subject": _card_subject(card),
                    "disposition": "no_impact",
                    "reason": MARKER_ROW_REASON,
                    "markers": markers,
                    "items": [],
                }
            )
    return rows


MARKER_ROW_REASON: Final = (
    "Update History no-impact attestation(s) moved here by the crossing sync (MIK-R24 rule 8 "
    "step 1); the marker lines are in 'markers'."
)


def marker_pieces(line: str) -> list[str]:
    """One marker line as history text values: itself, or consecutive pieces no longer than the
    text limit (split at the limit, so the same line always splits the same way)."""

    return [
        line[start : start + PROSE_MAX_LENGTH] for start in range(0, len(line), PROSE_MAX_LENGTH)
    ]


def with_markers(
    own: MemoryInput, owner: HistoryOwner, rows: list[dict[str, Any]]
) -> tuple[dict[str, bytes], list[dict[str, Any]]]:
    """The own tree with the marker rows in the leaf's history file, and the rows not moved.

    A marker whose subject already has a row in the history file is not moved (a file holds one
    row per subject, MIK-R07) and the existing, authored row is left as it is; the marker is
    returned so the crossing report names it -- never dropped silently.
    """

    path = history_path(owner.id)
    files = dict(own.files)
    existing = files.get(path)
    document: dict[str, Any] = (
        parse_json(existing.decode("utf-8"))
        if existing is not None
        else {"schema": "ar-history/v1", "leaf": owner.id, "closed": False, "rows": []}
    )
    known = {row["subject"] for row in document["rows"]}
    not_moved = [row for row in rows if row["subject"] in known]
    document["rows"] = [*document["rows"], *(row for row in rows if row["subject"] not in known)]
    files[path] = canonical_text(document).encode("utf-8")
    return files, [{"subject": row["subject"], "markers": row["markers"]} for row in not_moved]


def next_crossing_owner(task_id: str, *trees: Mapping[str, bytes]) -> str:
    """``<task-id>-crossing-<n>``: one more than any crossing file of this task on any side."""

    numbers = [
        int(match["n"])
        for tree in trees
        for path in tree
        if (match := _CROSSING_FILE.match(path)) and match["task"] == task_id
    ]
    return f"{task_id}-crossing-{max(numbers, default=0) + 1}"


Sides = tuple[MemoryInput, MemoryInput, MemoryInput]
_SIDE_NAMES: Final = ("base", "own", "incoming")


def _pinned_version(sides: Sides) -> str:
    if not any(tree.converted for tree in sides):
        raise CrossingError(
            "convert",
            "no tree of this merge is converted, so there is nothing to merge structurally",
        )
    versions = {version for version in map(_version, sides) if version is not None}
    if len(versions) != 1:
        raise CrossingError(
            "convert", f"converted sides disagree on the version: {sorted(versions)}"
        )
    return versions.pop()


def _convert_sides(
    sides: Sides, objects: CodeObjects, own_paired_commit: str, version: str
) -> dict[str, dict[str, bytes]]:
    converted: dict[str, dict[str, bytes]] = {}
    for name, tree in zip(_SIDE_NAMES, sides, strict=True):
        try:
            outcome = convert_memory(
                tree, objects, paired_commit=own_paired_commit, version=version
            )
        except ValueError as error:
            raise CrossingError("convert", f"{name} side: {error}") from error
        converted[name] = outcome.files
    return converted


def cross(
    sides: Sides,
    objects: CodeObjects,
    *,
    own_paired_commit: str,
    repository: Path,
    owner: HistoryOwner | None,
) -> CrossingPlan:
    """Run rule 8 steps 1-4 over (base, own, incoming); raise :class:`CrossingError` on failure."""

    base, own, _ = sides
    version = _pinned_version(sides)
    rows: list[dict[str, Any]] = []
    if owner is not None and owner.kind == "leaf" and not own.converted:
        try:
            rows = marker_rows(base, own)
        except (UnicodeDecodeError, ValueError) as error:
            raise CrossingError("markers", str(error)) from error
    converted = _convert_sides(sides, objects, own_paired_commit, version)
    not_moved: list[dict[str, Any]] = []
    if rows and owner is not None:
        converted["own"], not_moved = with_markers(
            MemoryInput(label=own.label, files=converted["own"], database=None), owner, rows
        )
    try:
        merged = merge_trees(*(converted[name] for name in _SIDE_NAMES), repository=repository)
    except (RuntimeError, ValueError) as error:
        raise CrossingError("merge", str(error)) from error
    plan = CrossingPlan(files=merged.files, conflicts=merged.conflicts)
    for path in merged.conflicted_paths:
        base_bytes, own_bytes, incoming_bytes = (converted[name].get(path) for name in _SIDE_NAMES)
        plan.conflict_versions[path] = (base_bytes, own_bytes, incoming_bytes)
    record_owner = None
    if owner is not None:
        record_owner = (
            owner.id if owner.kind == "leaf" else next_crossing_owner(owner.id, *converted.values())
        )
        if owner.kind == "master" and _record_conflicts(merged.conflicted_paths):
            # Rule 8 step 4: a master line has no leaf, so the resolved record's row goes into
            # <task-id>-crossing-<n>.json. The file is opened here for the curator's row and
            # closed by the sync in the merge commit itself.
            plan.files[history_path(record_owner)] = canonical_text(
                {"schema": "ar-history/v1", "crossing": record_owner, "closed": False, "rows": []}
            ).encode("utf-8")
    plan.report = {
        "version": version,
        "converted": [
            name for name, tree in zip(_SIDE_NAMES, sides, strict=True) if not tree.converted
        ],
        "markerRows": len(rows) - len(not_moved),
        "markersNotMoved": not_moved,
        "taken": dict(sorted(merged.taken.items())),
        "cards": _card_counts(converted, merged.files, merged.conflicted_paths),
        "conflicts": [one.to_document() for one in merged.conflicts],
        "recordConflictHistoryOwner": record_owner,
    }
    return plan


def _record_conflicts(paths: tuple[str, ...]) -> list[str]:
    """The conflicted paths that are knowledge records (not sidecars, history or the marker)."""

    directories = tuple(f"knowledge/{name}/" for name in RECORD_DIRECTORIES.values())
    return [path for path in paths if path.startswith(directories)]


def _card_counts(
    converted: Mapping[str, Mapping[str, bytes]],
    merged: Mapping[str, bytes | None],
    conflicted: tuple[str, ...],
) -> dict[str, int]:
    """Cards (Markdown) taken from each side, merged cleanly, or left conflicted."""

    counts = {"unchanged": 0, "fromOwn": 0, "fromIncoming": 0, "mergedClean": 0, "conflicted": 0}
    base, own, incoming = converted["base"], converted["own"], converted["incoming"]
    for path in merged:
        if not path.endswith(".md"):
            continue
        before, mine, theirs = base.get(path), own.get(path), incoming.get(path)
        if path in conflicted:
            counts["conflicted"] += 1
        elif mine == theirs:
            counts["unchanged"] += 1
        elif before == mine:
            counts["fromIncoming"] += 1
        elif before == theirs:
            counts["fromOwn"] += 1
        else:
            counts["mergedClean"] += 1
    return counts

"""Row codecs between the typed knowledge vocabulary and the declared columns.

Every conversion in both directions lives here, so the column order, the canonical JSON text
form of a typed column and the digest recomputation have exactly one owner. A reader that
decodes a row without recomputing its digest would accept a rewritten payload as its own
identity, so :func:`decode_revision_row` and :func:`decode_family_revision_row` verify the seal
on the way out.
"""

from __future__ import annotations

from collections.abc import Sequence
from typing import Any

from pydantic import TypeAdapter

from agents_remember.kernel.canonical_json import decoded_json, sha256_digest
from agents_remember.memory.knowledge.refusals import KnowledgeStorageError
from agents_remember.models.knowledge.authorship import ACCEPTED_STATE, PROPOSED_STATE, Authorship
from agents_remember.models.knowledge.base import KnowledgeState
from agents_remember.models.knowledge.digest import (
    family_revision_payload_digest,
    revision_payload_digest,
)
from agents_remember.models.knowledge.family import (
    FamilyIdentity,
    FamilyRevision,
    StoredFamilyRevision,
)
from agents_remember.models.knowledge.graph import (
    FamilyMember,
)
from agents_remember.models.knowledge.invariant import (
    InvariantIdentity,
    InvariantRevision,
    StoredInvariantRevision,
)
from agents_remember.models.knowledge.repository import RepositoryIdentity
from agents_remember.models.knowledge.source import (
    SourceLocator,
)

_LOCATOR_ADAPTER: TypeAdapter[Any] = TypeAdapter(SourceLocator)


def decode_typed_column(text: str) -> Any:
    """Decode one stored typed column, refusing ambiguous JSON."""

    return decoded_json(text)


def decode_authorship(text: str) -> Authorship:
    return Authorship.model_validate(decode_typed_column(text))


def decode_state_at_origin(value: object) -> KnowledgeState:
    """Narrow a stored origin state to the two authored states this schema admits."""

    text = str(value)
    if text == PROPOSED_STATE:
        return PROPOSED_STATE
    if text == ACCEPTED_STATE:
        return ACCEPTED_STATE
    raise KnowledgeStorageError(
        f"stored revision declares acceptance state {text!r}, which is not one of "
        f"{PROPOSED_STATE!r} or {ACCEPTED_STATE!r}"
    )


def decode_repository_row(row: Sequence[Any]) -> RepositoryIdentity:
    return RepositoryIdentity(repository_id=str(row[0]), authority_home=str(row[1]))


def invariant_row_digest(
    repository_id: str, invariant_id: str, display_label: str, provenance: Authorship
) -> str:
    """Digest one invariant identity row so a label edit can name the row it expects."""

    return sha256_digest(
        {
            "table": "invariant",
            "repository_id": repository_id,
            "invariant_id": invariant_id,
            "display_label": display_label,
            "label_provenance": provenance.model_dump(mode="json"),
        }
    )


def decode_invariant_row(row: Sequence[Any]) -> InvariantIdentity:
    repository_id, invariant_id, display_label = str(row[0]), str(row[1]), str(row[2])
    provenance = decode_authorship(str(row[3]))
    return InvariantIdentity(
        repository_id=repository_id,
        invariant_id=invariant_id,
        display_label=display_label,
        label_provenance=provenance,
        row_digest=invariant_row_digest(repository_id, invariant_id, display_label, provenance),
    )


def decode_revision_row(
    row: Sequence[Any], predecessors: tuple[str, ...]
) -> StoredInvariantRevision:
    """Decode one revision row and verify that its stored seal still holds.

    The verification is the point: a row whose text was rewritten behind its identity would
    otherwise be served as if it were the revision that identity names.
    """

    revision = InvariantRevision(
        repository_id=str(row[0]),
        invariant_id=str(row[1]),
        revision_id=str(row[2]),
        display_version=str(row[3]),
        statement=str(row[4]),
        applicability=str(row[5]),
        conditions=tuple(str(item) for item in decode_typed_column(str(row[6]))),
        exclusions=tuple(str(item) for item in decode_typed_column(str(row[7]))),
        state_at_origin=decode_state_at_origin(row[8]),
        acceptance_ref=None if row[9] is None else str(row[9]),
        provenance=decode_authorship(str(row[10])),
        predecessors=tuple(sorted(predecessors)),
        payload_digest=str(row[11]),
    )
    recomputed = revision_payload_digest(revision)
    if recomputed != revision.payload_digest:
        raise KnowledgeStorageError(
            f"stored revision {revision.revision_id} does not match its payload digest: "
            f"stored {revision.payload_digest}, recomputed {recomputed}. The row was altered "
            "behind its identity; treat the store as damaged and recover the revision from an "
            "intact snapshot."
        )
    return StoredInvariantRevision(revision=revision)


def decode_predecessor_rows(rows: Sequence[Sequence[Any]]) -> tuple[str, ...]:
    return tuple(sorted(str(row[0]) for row in rows))


def family_row_digest(
    repository_id: str, family_id: str, display_label: str, provenance: Authorship
) -> str:
    """Digest one family identity row so a label edit can name the row it expects."""

    return sha256_digest(
        {
            "table": "family",
            "repository_id": repository_id,
            "family_id": family_id,
            "display_label": display_label,
            "label_provenance": provenance.model_dump(mode="json"),
        }
    )


def decode_family_row(row: Sequence[Any]) -> FamilyIdentity:
    repository_id, family_id, display_label = str(row[0]), str(row[1]), str(row[2])
    provenance = decode_authorship(str(row[3]))
    return FamilyIdentity(
        repository_id=repository_id,
        family_id=family_id,
        display_label=display_label,
        label_provenance=provenance,
        row_digest=family_row_digest(repository_id, family_id, display_label, provenance),
    )


def decode_family_revision_row(
    row: Sequence[Any], predecessors: tuple[str, ...]
) -> StoredFamilyRevision:
    """Decode one family revision row and verify that its stored seal still holds."""

    revision = FamilyRevision(
        repository_id=str(row[0]),
        family_id=str(row[1]),
        revision_id=str(row[2]),
        display_version=str(row[3]),
        joint_guarantee=str(row[4]),
        state_at_origin=decode_state_at_origin(row[5]),
        acceptance_ref=None if row[6] is None else str(row[6]),
        provenance=decode_authorship(str(row[7])),
        predecessors=tuple(sorted(predecessors)),
        payload_digest=str(row[8]),
    )
    recomputed = family_revision_payload_digest(revision)
    if recomputed != revision.payload_digest:
        raise KnowledgeStorageError(
            f"stored family revision {revision.revision_id} does not match its payload digest: "
            f"stored {revision.payload_digest}, recomputed {recomputed}. The row was altered "
            "behind its identity; treat the store as damaged and recover the revision from an "
            "intact snapshot."
        )
    return StoredFamilyRevision(revision=revision)


def member_row_digest(
    repository_id: str,
    member_id: str,
    family_revision_id: str,
    invariant_revision_id: str,
    provenance: Authorship,
) -> str:
    """Digest one membership row so an explicit removal can name the row it expects."""

    return sha256_digest(
        {
            "table": "family_member",
            "repository_id": repository_id,
            "member_id": member_id,
            "family_revision_id": family_revision_id,
            "invariant_revision_id": invariant_revision_id,
            "provenance": provenance.model_dump(mode="json"),
        }
    )


def decode_member_row(row: Sequence[Any]) -> FamilyMember:
    repository_id, member_id = str(row[0]), str(row[1])
    family_revision_id, invariant_revision_id = str(row[2]), str(row[3])
    provenance = decode_authorship(str(row[4]))
    return FamilyMember(
        repository_id=repository_id,
        member_id=member_id,
        family_revision_id=family_revision_id,
        invariant_revision_id=invariant_revision_id,
        provenance=provenance,
        row_digest=member_row_digest(
            repository_id, member_id, family_revision_id, invariant_revision_id, provenance
        ),
    )

"""Generate citation ranges for anchors inside one file.

Identifier anchors use binding extents, headings run to the next equal/higher heading, and
quoted literals use their occupied lines. Direct JavaScript/TypeScript string arguments
widen to the enclosing call. Every candidate is returned so the resolver can refuse
ambiguity.

Parsed-language ownership comes from ``grammars``. Other suffixes use occurrence ranges;
a mention is then indistinguishable from a declaration, so occurrence matching cannot
prove a pure move.

Use ``FileView`` for batches so parsing, words, and heading levels are derived once per
file. TypeScript false-positive boundaries: strip ``//`` only at line starts, widen only a
direct call argument, and match the exact byte occurrence so identical callback,
assignment, comment, and same-line strings remain separate.
"""

from __future__ import annotations

import re
from dataclasses import dataclass

from agents_remember.memory_quality.style.citations import grammars, model
from agents_remember.memory_quality.style.document_shape import inline_scan

DEFINITION = "definition"
OCCURRENCE = "occurrence"
SECTION = "section"
QUOTED = "quoted"
CALL = "call"

HEADING_LINE = re.compile(r"^(#{1,6})\s")

# Re-exported so nothing outside :mod:`grammars` has to know a suffix to ask whether a
# definition in a file is distinguishable from a mention of it.
parsed = grammars.parsed


@dataclass(frozen=True)
class Extent:
    """One range an anchor occupies in a file, and how it was found."""

    start: int
    end: int
    kind: str
    # For a DEFINITION extent, the line the declaration itself begins on. It differs from
    # ``start`` for a decorated definition, whose extent is widened to cover its decorator: the
    # anchor names the declaration, and a citation that starts at the declaration's own first
    # line is about that construct. ``None`` for every other kind, where the two coincide.
    declaration: int | None = None

    def holds(self, start: int, end: int) -> bool:
        """Whether this extent overlaps the range ``start``-``end`` at all."""
        return self.start <= end and start <= self.end


@dataclass(frozen=True)
class WordMark:
    """One collapsed word and the byte position it retains from the source."""

    collapsed_start: int
    collapsed_end: int
    line: int
    source_byte_start: int
    text: str


@dataclass(frozen=True)
class CollapsedText:
    """Whitespace-collapsed text whose word marks still identify source bytes."""

    text: str
    marks: tuple[WordMark, ...]


@dataclass(frozen=True)
class QuoteMatch:
    """One exact quote occurrence before line-range rendering merges equal extents."""

    start: int
    end: int
    source_byte_start: int
    source_byte_end: int

    @property
    def extent(self) -> Extent:
        return Extent(start=self.start, end=self.end, kind=QUOTED)


def anchor_extents(anchor: model.Anchor, path: str, lines: list[str]) -> tuple[Extent, ...]:
    """Every range in ``lines`` that satisfies ``anchor``, by the rule its kind implies."""
    if anchor.kind == model.SYMBOL:
        return symbol_extents(anchor.text, path, lines)
    if anchor.kind == model.HEADING:
        return heading_extents(anchor.text, lines)
    return quote_extents_for_path(anchor.text, path, lines)


def symbol_extents(name: str, path: str, lines: list[str]) -> tuple[Extent, ...]:
    """The constructs binding ``name``, or -- failing that -- the lines that mention it."""
    bound = definitions(path, lines).get(name, ())
    if bound:
        return tuple(bound)
    return occurrence_runs(model.whole_identifier(name), lines)


def definitions(path: str, lines: list[str]) -> dict[str, list[Extent]]:
    """Every name this file binds at any depth, and the extent of the construct binding it.

    Assignments and declarators count, not only ``def`` and ``class``: an earlier
    measurement of this surface collected definitions only and read badly, because these
    documents cite module-level constants constantly. A file in a language with no grammar,
    and a construct too broken to parse, bind nothing and drop to occurrence matching
    rather than failing the run -- the tree holds source written for other dialects and
    none of it is this check's business. A grammar that will not LOAD is the other case
    entirely and raises; see :mod:`grammars`.
    """
    return {
        name: [
            Extent(
                start=binding.span[0],
                end=binding.span[1],
                kind=DEFINITION,
                declaration=binding.declaration,
            )
            for binding in items
        ]
        for name, items in grammars.bindings(path, lines).items()
    }


def qualified_spans(name: str, bound: dict[str, list[Extent]]) -> tuple[tuple[int, int], ...]:
    """The distinct extents binding ``name`` in one file's :func:`definitions`.

    ``Holder.method`` is the ``method`` defined inside a ``Holder`` definition, so a same-named
    method of another class in the file does not make the name ambiguous. A symbol anchor names one
    construct only when exactly one span comes back; the curator writer (MIK-R12) and the
    conversion (MIK-R24) both bind symbols through this one rule.
    """
    parts = [part for part in name.split(".") if part]
    if not parts or any(part not in bound for part in parts):
        return ()
    candidates = list(bound[parts[-1]])
    for parent in parts[:-1]:
        holders = bound[parent]
        candidates = [
            one
            for one in candidates
            if any(holder.start <= one.start and one.end <= holder.end for holder in holders)
        ]
    return tuple(dict.fromkeys((extent.start, extent.end) for extent in candidates))


def occurrence_runs(pattern: re.Pattern[str], lines: list[str]) -> tuple[Extent, ...]:
    """Consecutive lines holding the pattern, grouped -- two mentions ten lines apart are
    two ranges, because one range spanning them would quote eight lines that say nothing."""
    hits = [index + 1 for index, line in enumerate(lines) if pattern.search(line)]
    found: list[Extent] = []
    for line in hits:
        if found and found[-1].end == line - 1:
            found[-1] = Extent(start=found[-1].start, end=line, kind=OCCURRENCE)
            continue
        found.append(Extent(start=line, end=line, kind=OCCURRENCE))
    return tuple(found)


def heading_extents(heading: str, lines: list[str]) -> tuple[Extent, ...]:
    """The section a heading opens: its own line to the line before the next heading of
    equal or higher level, or to the end of the document."""
    return heading_extents_in(heading, lines, heading_levels(inline_scan.unfenced_lines(lines)))


def heading_extents_in(
    heading: str, lines: list[str], levels: dict[int, int]
) -> tuple[Extent, ...]:
    """:func:`heading_extents` with the file's heading levels already derived."""
    opening = len(heading) - len(heading.lstrip("#"))
    found: list[Extent] = []
    for index in sorted(levels):
        if lines[index].strip() != heading:
            continue
        closing = next(
            (later for later in sorted(levels) if later > index and levels[later] <= opening),
            len(lines),
        )
        found.append(Extent(start=index + 1, end=closing, kind=SECTION))
    return tuple(found)


def heading_levels(unfenced: list[tuple[int, str]]) -> dict[int, int]:
    """Each unfenced heading line's index and its ``#`` depth."""
    matched = ((index, HEADING_LINE.match(line.strip())) for index, line in unfenced)
    return {index: len(match.group(1)) for index, match in matched if match is not None}


def quote_extents_for_path(quote: str, path: str, lines: list[str]) -> tuple[Extent, ...]:
    """Quoted extents with parsed-language call-argument widening."""
    matches = all_quote_matches(quote, collapsed(lines), line_comment_blocks(lines))
    return widened_quotes(quote, matches, grammars.call_argument_literals(path, lines))


def all_quote_matches(
    quote: str,
    words: CollapsedText,
    comments: tuple[CollapsedText, ...],
) -> tuple[QuoteMatch, ...]:
    found = list(quote_matches_in(quote, words))
    for block in comments:
        found.extend(quote_matches_in(quote, block))
    return tuple(
        dict.fromkeys(
            sorted(
                found,
                key=lambda one: (
                    one.source_byte_start,
                    one.source_byte_end,
                    one.start,
                    one.end,
                ),
            )
        )
    )


def widened_quotes(
    quote: str,
    matches: tuple[QuoteMatch, ...],
    calls: tuple[grammars.CallLiteral, ...],
) -> tuple[Extent, ...]:
    widened: list[Extent] = []
    covered: set[tuple[int, int]] = set()
    anchor = model.Anchor(kind=model.QUOTE, text=quote)
    for call in calls:
        if not model.occurs_in(anchor, call.text):
            continue
        widened.append(Extent(start=call.start, end=call.end, kind=CALL))
        covered.update(
            (match.source_byte_start, match.source_byte_end)
            for match in matches
            if call.argument_start_byte <= match.source_byte_start
            and match.source_byte_end <= call.argument_end_byte
        )
    widened.extend(
        match.extent
        for match in matches
        if (match.source_byte_start, match.source_byte_end) not in covered
    )
    return tuple(dict.fromkeys(sorted(widened, key=lambda one: (one.start, one.end, one.kind))))


def quote_matches_in(quote: str, stream: CollapsedText) -> tuple[QuoteMatch, ...]:
    """Exact occurrences in one collapsed stream, with source-byte identity retained."""
    target = model.normalised(quote)
    if not target:
        return ()
    found: list[QuoteMatch] = []
    at = stream.text.find(target)
    while at >= 0:
        end = at + len(target)
        first = word_mark_at(stream.marks, at)
        last = word_mark_at(stream.marks, end - 1)
        found.append(
            QuoteMatch(
                start=first.line,
                end=last.line,
                source_byte_start=(
                    first.source_byte_start
                    + len(first.text[: at - first.collapsed_start].encode("utf-8"))
                ),
                source_byte_end=(
                    last.source_byte_start
                    + len(last.text[: end - last.collapsed_start].encode("utf-8"))
                ),
            )
        )
        at = stream.text.find(target, at + 1)
    return tuple(found)


def collapsed(lines: list[str]) -> CollapsedText:
    """The file as whitespace-collapsed text with each word's line and byte position."""
    words: list[str] = []
    marks: list[WordMark] = []
    width = 0
    line_starts = source_line_starts(lines)
    for index, line in enumerate(lines):
        for matched in re.finditer(r"\S+", line):
            word = matched.group()
            marks.append(
                WordMark(
                    collapsed_start=width,
                    collapsed_end=width + len(word),
                    line=index + 1,
                    source_byte_start=(
                        line_starts[index] + len(line[: matched.start()].encode("utf-8"))
                    ),
                    text=word,
                )
            )
            words.append(word)
            width += len(word) + 1
    return CollapsedText(" ".join(words), tuple(marks))


def line_comment_blocks(
    lines: list[str],
) -> tuple[CollapsedText, ...]:
    """Contiguous ``//`` blocks with syntax prefixes removed and source lines retained."""
    found: list[CollapsedText] = []
    words: list[str] = []
    marks: list[WordMark] = []
    width = 0
    line_starts = source_line_starts(lines)
    for index, line in enumerate(lines):
        matched = re.match(r"^\s*//\s?", line)
        if matched is None:
            if words:
                found.append(CollapsedText(" ".join(words), tuple(marks)))
            words, marks, width = [], [], 0
            continue
        for word_match in re.finditer(r"\S+", line[matched.end() :]):
            word = word_match.group()
            source_start = matched.end() + word_match.start()
            marks.append(
                WordMark(
                    collapsed_start=width,
                    collapsed_end=width + len(word),
                    line=index + 1,
                    source_byte_start=(
                        line_starts[index] + len(line[:source_start].encode("utf-8"))
                    ),
                    text=word,
                )
            )
            words.append(word)
            width += len(word) + 1
    if words:
        found.append(CollapsedText(" ".join(words), tuple(marks)))
    return tuple(found)


def word_mark_at(marks: tuple[WordMark, ...], offset: int) -> WordMark:
    """The source word containing a non-whitespace collapsed-text offset."""
    low = 0
    high = len(marks)
    while low < high:
        middle = (low + high) // 2
        if marks[middle].collapsed_start <= offset:
            low = middle + 1
        else:
            high = middle
    if low == 0:
        raise StopIteration
    found = marks[low - 1]
    if offset >= found.collapsed_end:
        raise StopIteration
    return found


def source_line_starts(lines: list[str]) -> list[int]:
    """UTF-8 byte offset of every line in the exact source tree-sitter parses."""
    starts: list[int] = []
    width = 0
    for line in lines:
        starts.append(width)
        width += len(line.encode("utf-8")) + 1
    return starts


@dataclass
class FileView:
    """One file, matched against many anchors, with each whole-file derivation done once.

    Hold one per file for as long as the batch lasts. Every derivation is lazy, so a file
    no quoted anchor is asked about never builds its word stream.
    """

    path: str
    lines: list[str]
    _names: set[str] | None = None
    _defined: dict[str, list[Extent]] | None = None
    _collapsed: CollapsedText | None = None
    _comments: tuple[CollapsedText, ...] | None = None
    _levels: dict[int, int] | None = None
    _calls: tuple[grammars.CallLiteral, ...] | None = None

    def extents(self, anchor: model.Anchor) -> tuple[Extent, ...]:
        """Every range in this file that satisfies ``anchor`` -- :func:`anchor_extents`."""
        if anchor.kind == model.SYMBOL:
            return self._symbol(anchor.text)
        if anchor.kind == model.HEADING:
            return heading_extents_in(anchor.text, self.lines, self.headings())
        return widened_quotes(
            anchor.text,
            all_quote_matches(anchor.text, self.words(), self.comments()),
            self.calls(),
        )

    def words(self) -> CollapsedText:
        if self._collapsed is None:
            self._collapsed = collapsed(self.lines)
        return self._collapsed

    def headings(self) -> dict[int, int]:
        if self._levels is None:
            self._levels = heading_levels(inline_scan.unfenced_lines(self.lines))
        return self._levels

    def comments(self) -> tuple[CollapsedText, ...]:
        if self._comments is None:
            self._comments = line_comment_blocks(self.lines)
        return self._comments

    def calls(self) -> tuple[grammars.CallLiteral, ...]:
        if self._calls is None:
            self._calls = grammars.call_argument_literals(self.path, self.lines)
        return self._calls

    def _symbol(self, name: str) -> tuple[Extent, ...]:
        """The name test first: it rejects most files without parsing or scanning them."""
        if self._names is None:
            self._names = set(model.IDENTIFIER_PATTERN.findall("\n".join(self.lines)))
        if name not in self._names:
            return ()
        if self._defined is None:
            self._defined = definitions(self.path, self.lines)
        bound = self._defined.get(name, ())
        if bound:
            return tuple(bound)
        return occurrence_runs(model.whole_identifier(name), self.lines)


def merged(spans: list[tuple[int, int]]) -> tuple[tuple[int, int], ...]:
    """``spans`` in order with overlapping and adjacent ones fused into one range."""
    found: list[tuple[int, int]] = []
    for start, end in sorted(spans):
        if found and start <= found[-1][1] + 1:
            found[-1] = (found[-1][0], max(found[-1][1], end))
            continue
        found.append((start, end))
    return tuple(found)

"""Reopen a completed leaf TASK under its exact same leaf id (the ``task_reopen`` tool).

Reopen resets a leaf's task state, and it does that by REWRITING THE LEAF'S ENCLOSURE
CONTRACT — which is why it lives here rather than in ``tasks``. It reads and amends the
contract, emits a ``WorktreeCommandResult``, and renders its report through the worktree
status payload; the document reset is the smaller half, and it goes through the ``tasks``
package the same way every other worktree operation does. Ranked the other way round it
made ``tasks`` and ``worktrees`` mutually dependent (``layers.toml``): the task document
store could not be loaded without loading the whole worktree lifecycle, for one function
that is a worktree lifecycle operation wearing a task-shaped name.

Historically, restarting a finished leaf meant minting a suffixed leaf id (``…-r1``):
a new enclosure and lifecycle while the doc, chats, and dashboard rows stayed keyed to
the original leaf — a forked identity no join could follow. ``task_reopen`` resets the
one true leaf instead:

- contract: the three progress blockers back to their virgin state (``human_review``
  pending / unapproved, ``closeout`` and ``integration`` not-started), the stale
  ``lifecycle.id`` cleared, and ``cleanup: reopened`` as the marker ``worktree_start``
  recreates fresh from (same tombstone semantics as ``abandoned``);
- doc: status back to ``planning``, its ``lifecycleId`` cleared (the next
  ``worktree_start`` restamps it with the fresh lifecycle), the master's sub-task
  index entry flipped back, and an audit decision appended.

The agent then edits steps via ``task_doc`` and runs a NORMAL ``worktree_start`` with
the same leaf id: worktrees and branches are recreated off the current source tips, a
fresh lifecycle is promoted/minted, and every binding holds by construction because
the leaf id never changed.
"""

